--
-- Name: derived_write_guard(); Type: FUNCTION; Schema: analysis; Owner: -
--

CREATE FUNCTION analysis.derived_write_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF current_setting('app.enforce_derived_guard', true) IS DISTINCT FROM 'on' THEN
    RETURN NEW;                      -- guard not armed
  END IF;
  IF current_setting('app.deriving', true) = 'on' THEN
    RETURN NEW;                      -- the deriver is allowed
  END IF;
  RAISE EXCEPTION USING MESSAGE =
    'analysis.' || TG_TABLE_NAME
    || ' is a DERIVED table: write it only from the derivation pass '
    || '(SET LOCAL app.deriving = ''on''). Raw is the single insert target.';
END;
$$;


--
-- Name: entity_candidate_no_mutate(); Type: FUNCTION; Schema: analysis; Owner: -
--

CREATE FUNCTION analysis.entity_candidate_no_mutate() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.entity_text  IS DISTINCT FROM OLD.entity_text
     OR NEW.record_id IS DISTINCT FROM OLD.record_id
     OR NEW.extractor IS DISTINCT FROM OLD.extractor
     OR NEW.span_start IS DISTINCT FROM OLD.span_start
     OR NEW.span_end   IS DISTINCT FROM OLD.span_end THEN
    RAISE EXCEPTION
      'analysis.entity_candidate is append-only: insert a new row instead of editing the claim';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: extraction_candidate_no_mutate(); Type: FUNCTION; Schema: analysis; Owner: -
--

CREATE FUNCTION analysis.extraction_candidate_no_mutate() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.entity_text  IS DISTINCT FROM OLD.entity_text
     OR NEW.record_id IS DISTINCT FROM OLD.record_id
     OR NEW.extractor IS DISTINCT FROM OLD.extractor
     OR NEW.candidate_kind IS DISTINCT FROM OLD.candidate_kind
     OR NEW.span_start IS DISTINCT FROM OLD.span_start
     OR NEW.span_end   IS DISTINCT FROM OLD.span_end THEN
    RAISE EXCEPTION USING MESSAGE =
      'analysis.extraction_candidate is append-only: insert a new row instead of '
      'editing the claim (review columns and consumed_by are the mutable surface)';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: knowledge_evidence_pointer_hash(jsonb); Type: FUNCTION; Schema: analysis; Owner: -
--

CREATE FUNCTION analysis.knowledge_evidence_pointer_hash(pointer jsonb) RETURNS bytea
    LANGUAGE sql IMMUTABLE STRICT
    AS $$
    SELECT public.digest(
        convert_to(
            jsonb_build_object(
                'matter_id', pointer -> 'matter_id',
                'court_case_id', pointer -> 'court_case_id',
                'partition_key', pointer -> 'partition_key',
                'lane', pointer -> 'lane',
                'normalized_record_id', pointer -> 'normalized_record_id',
                'evidence_hash_id', pointer -> 'evidence_hash_id',
                'source_id', pointer -> 'source_id',
                'sha256', pointer -> 'sha256',
                'conversation_id', pointer -> 'conversation_id',
                'quote', pointer -> 'quote'
            )::text,
            'UTF8'
        ),
        'sha256'
    )
$$;


--
-- Name: log_task_status(); Type: FUNCTION; Schema: analysis; Owner: -
--

CREATE FUNCTION analysis.log_task_status() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ BEGIN
    IF NEW.status IS DISTINCT FROM OLD.status THEN
      IF NEW.status = 'archived' AND COALESCE(NEW.archive_reason,'') = '' THEN
        RAISE EXCEPTION 'archived status requires archive_reason (no silent discard)';
      END IF;
      INSERT INTO analysis.task_event(task_id, from_status, to_status, actor, actor_kind, reason, ts)
      VALUES (NEW.id, OLD.status, NEW.status, COALESCE(current_setting('app.actor', true),'system'),
              COALESCE(current_setting('app.actor_kind', true),'system'), NEW.archive_reason, now());
    END IF; RETURN NEW; END $$;


--
-- Name: record_graphrag_comparison_join(uuid, text, text, uuid, bytea, uuid, uuid); Type: FUNCTION; Schema: analysis; Owner: -
--

CREATE FUNCTION analysis.record_graphrag_comparison_join(p_run_id uuid, p_stage_id text, p_stage_version text, p_manifest_id uuid, p_manifest_digest bytea, p_semantica_receipt_id uuid, p_sat_temporal_receipt_id uuid) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE v_id UUID;
BEGIN
  INSERT INTO analysis.graphrag_comparison_join (
    run_id, stage_id, stage_version, manifest_id, manifest_digest,
    semantica_receipt_id, sat_temporal_receipt_id)
  VALUES (p_run_id, p_stage_id, p_stage_version, p_manifest_id, p_manifest_digest,
          p_semantica_receipt_id, p_sat_temporal_receipt_id)
  ON CONFLICT (run_id, stage_id, stage_version, manifest_id, manifest_digest) DO UPDATE
    SET semantica_receipt_id    = COALESCE(EXCLUDED.semantica_receipt_id,    analysis.graphrag_comparison_join.semantica_receipt_id),
        sat_temporal_receipt_id = COALESCE(EXCLUDED.sat_temporal_receipt_id, analysis.graphrag_comparison_join.sat_temporal_receipt_id)
  RETURNING id INTO v_id;
  RETURN v_id;
END $$;


--
-- Name: seal_graphrag_manifest(uuid); Type: FUNCTION; Schema: analysis; Owner: -
--

CREATE FUNCTION analysis.seal_graphrag_manifest(p_manifest_id uuid) RETURNS TABLE(manifest_id uuid, membership_digest bytea, member_count integer, sealed_at timestamp with time zone)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_digest BYTEA;
  v_count  INTEGER;
  v_now    TIMESTAMPTZ := now();
BEGIN
  SELECT count(*)::INTEGER,
         digest(coalesce(string_agg(
           m.ordinal::TEXT || ':' || m.source_version_id::TEXT || ':' ||
           m.normalized_record_id::TEXT || ':' || coalesce(m.text_unit_id::TEXT,''),
           '|' ORDER BY m.ordinal), ''), 'sha256')
    INTO v_count, v_digest
    FROM analysis.graphrag_eligibility_manifest_member m
   WHERE m.manifest_id = p_manifest_id;

  UPDATE analysis.graphrag_eligibility_manifest
     SET status = 'sealed', membership_digest = v_digest,
         member_count = v_count, sealed_at = v_now
   WHERE id = p_manifest_id;

  RETURN QUERY SELECT p_manifest_id, v_digest, v_count, v_now;
END $$;


--
-- Name: set_case_management_updated_at(); Type: FUNCTION; Schema: analysis; Owner: -
--

CREATE FUNCTION analysis.set_case_management_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    NEW.updated_at := now();
    RETURN NEW;
END;
$$;


--
-- Name: snapshot_task(); Type: FUNCTION; Schema: analysis; Owner: -
--

CREATE FUNCTION analysis.snapshot_task() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ BEGIN
    INSERT INTO analysis.task_revision(task_id, snapshot, changed_by, change_note, ts)
    VALUES (OLD.id, to_jsonb(OLD), COALESCE(current_setting('app.actor', true),'unknown'),
            'auto-snapshot before UPDATE', now());
    RETURN NEW; END $$;


--
-- Name: apply_proposal(uuid, uuid); Type: FUNCTION; Schema: canon; Owner: -
--

CREATE FUNCTION canon.apply_proposal(p_proposal_id uuid, p_decision_id uuid) RETURNS uuid
    LANGUAGE plpgsql
    AS $_$
DECLARE
  v_p        canon.change_proposal%ROWTYPE;
  v_ct       canon.canonical_table%ROWTYPE;
  v_prior    JSONB := '{}'::jsonb;
  v_app_id   UUID;
  v_col      TEXT;
  v_pk_col   TEXT;
  v_pk_val   TEXT;
  v_set_sql  TEXT := '';
  v_tgt      TEXT;
BEGIN
  SELECT * INTO v_p  FROM canon.change_proposal  WHERE id = p_proposal_id FOR UPDATE;
  IF v_p.id IS NULL THEN RAISE EXCEPTION 'proposal % not found', p_proposal_id; END IF;
  IF v_p.status NOT IN ('proposed','approved') THEN
    RAISE EXCEPTION 'proposal % is %, not applicable', p_proposal_id, v_p.status;
  END IF;
  SELECT * INTO v_ct FROM canon.canonical_table  WHERE id = v_p.canonical_table_id FOR UPDATE;

  -- STALENESS GUARD: reasoned against a superseded generation -> requeue, never apply
  IF v_p.source_generation <> v_ct.current_generation THEN
    UPDATE canon.change_proposal SET status = 'stale_requeued' WHERE id = p_proposal_id;
    RETURN NULL;
  END IF;

  -- Only 'correct' patches are applied generically here; other kinds record the
  -- ruling + receipt and are executed by their kind-specific worker off the queue.
  IF v_p.proposal_kind = 'correct' THEN
    SELECT key, value #>> '{}' INTO v_pk_col, v_pk_val
      FROM jsonb_each(v_p.target_pk) LIMIT 1;
    -- snapshot prior values of exactly the patched columns
    EXECUTE format('SELECT to_jsonb(t) FROM %I.%I t WHERE %I = $1::uuid',
                   v_ct.table_schema, v_ct.table_name, v_pk_col)
      INTO v_prior USING v_pk_val;
    IF v_prior IS NULL THEN RAISE EXCEPTION 'target row not found for proposal %', p_proposal_id; END IF;
    SELECT jsonb_object_agg(k, v_prior -> k) INTO v_prior
      FROM jsonb_object_keys(v_p.patch) k;
    -- build and run the update
    SELECT string_agg(format('%I = ($1::jsonb ->> %L)::%s', key,
             key,
             (SELECT format_type(a.atttypid, a.atttypmod)
                FROM pg_attribute a
               WHERE a.attrelid = format('%I.%I', v_ct.table_schema, v_ct.table_name)::regclass
                 AND a.attname = key AND a.attnum > 0)), ', ')
      INTO v_set_sql
      FROM jsonb_each(v_p.patch);
    EXECUTE format('UPDATE %I.%I SET %s WHERE %I = $2::uuid',
                   v_ct.table_schema, v_ct.table_name, v_set_sql, v_pk_col)
      USING v_p.patch, v_pk_val;
  END IF;

  UPDATE canon.canonical_table
     SET current_generation = current_generation + 1
   WHERE id = v_ct.id;

  INSERT INTO canon.change_application
      (proposal_id, decision_id, prior_values, applied_patch, generation_before, generation_after)
  VALUES (p_proposal_id, p_decision_id, coalesce(v_prior,'{}'::jsonb), v_p.patch,
          v_ct.current_generation, v_ct.current_generation + 1)
  RETURNING id INTO v_app_id;

  FOREACH v_tgt IN ARRAY v_ct.recompute_targets LOOP
    INSERT INTO canon.recompute_queue
        (application_id, canonical_table_id, target_pk, recompute_target)
    VALUES (v_app_id, v_ct.id, v_p.target_pk, v_tgt);
  END LOOP;

  UPDATE canon.change_proposal SET status = 'applied' WHERE id = p_proposal_id;
  RETURN v_app_id;
END $_$;


--
-- Name: FUNCTION apply_proposal(p_proposal_id uuid, p_decision_id uuid); Type: COMMENT; Schema: canon; Owner: -
--

COMMENT ON FUNCTION canon.apply_proposal(p_proposal_id uuid, p_decision_id uuid) IS 'Adoption: staleness-checked against canonical_table.current_generation, snapshots prior values, applies the patch (correct-kind generically; other kinds via their workers), bumps the generation, enqueues recompute rows — one transaction.';


--
-- Name: route_tier(uuid, numeric); Type: FUNCTION; Schema: canon; Owner: -
--

CREATE FUNCTION canon.route_tier(p_canonical_table_id uuid, p_confidence numeric) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT CASE
    WHEN ct.auto_confirm_min_confidence IS NOT NULL
     AND p_confidence IS NOT NULL
     AND p_confidence >= ct.auto_confirm_min_confidence
    THEN 'auto_adopt'
    ELSE ct.default_tier
  END
  FROM canon.canonical_table ct WHERE ct.id = p_canonical_table_id
$$;


--
-- Name: FUNCTION route_tier(p_canonical_table_id uuid, p_confidence numeric); Type: COMMENT; Schema: canon; Owner: -
--

COMMENT ON FUNCTION canon.route_tier(p_canonical_table_id uuid, p_confidence numeric) IS 'Clear signal rides through logged; sketchy signal waits for the owner. Producers call this when filing a change_proposal to set its tier.';


--
-- Name: guard_hash_batch_insert(); Type: FUNCTION; Schema: context; Owner: -
--

CREATE FUNCTION context.guard_hash_batch_insert() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'context'
    AS $$
BEGIN
    PERFORM context.assert_source_version_retained(NEW.source_version_id);
    IF NEW.hash_kind IN ('context_raw_record_fingerprint', 'context_raw_generation_fingerprint') THEN
        PERFORM context.assert_raw_generation_open(NEW.raw_generation_id);
    ELSIF NEW.hash_kind IN ('normalized_record_digest', 'normalized_generation_manifest_digest') THEN
        PERFORM context.assert_normalized_generation_open(NEW.normalized_generation_id);
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: guard_normalized_generation_transition(); Type: FUNCTION; Schema: context; Owner: -
--

CREATE FUNCTION context.guard_normalized_generation_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.status = 'open' AND NEW.status = 'sealed' THEN
        IF NEW.id IS DISTINCT FROM OLD.id
           OR NEW.source_version_id IS DISTINCT FROM OLD.source_version_id
           OR NEW.raw_generation_id IS DISTINCT FROM OLD.raw_generation_id
           OR NEW.generation_ordinal IS DISTINCT FROM OLD.generation_ordinal
           OR NEW.normalizer_id IS DISTINCT FROM OLD.normalizer_id
           OR NEW.normalizer_version IS DISTINCT FROM OLD.normalizer_version
           OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
            RAISE EXCEPTION 'sealed normalized generation identity and normalizer provenance are immutable';
        END IF;
        IF NOT EXISTS (SELECT 1 FROM context.raw_generation raw
                       WHERE raw.id = NEW.raw_generation_id AND raw.status = 'sealed') THEN
            RAISE EXCEPTION 'normalized generation % cannot seal before raw generation % is sealed',
                NEW.id, NEW.raw_generation_id;
        END IF;
        IF NOT EXISTS (
            SELECT 1 FROM context.normalized_record_identity normalized
            WHERE normalized.normalized_generation_id = NEW.id
        ) THEN
            RAISE EXCEPTION 'normalized generation % cannot seal with zero records', NEW.id;
        END IF;
        IF EXISTS (
            SELECT 1
            FROM (
                SELECT record_ordinal,
                       row_number() OVER (ORDER BY record_ordinal) - 1 AS expected_ordinal
                FROM context.normalized_record_identity
                WHERE normalized_generation_id = NEW.id
            ) ordinals
            WHERE record_ordinal <> expected_ordinal
        ) THEN
            RAISE EXCEPTION 'normalized generation % has non-contiguous record ordinals', NEW.id;
        END IF;
        IF EXISTS (
            SELECT 1 FROM context.normalized_record_identity normalized
            WHERE normalized.normalized_generation_id = NEW.id
              AND NOT EXISTS (
                  SELECT 1 FROM context.normalization_lineage lineage
                  WHERE lineage.normalized_record_id = normalized.id
              )
        ) THEN
            RAISE EXCEPTION 'normalized generation % cannot seal without raw-record lineage for every member', NEW.id;
        END IF;
        IF EXISTS (
            SELECT 1 FROM context.normalized_record_identity normalized
            WHERE normalized.normalized_generation_id = NEW.id
              AND NOT EXISTS (
                  SELECT 1 FROM context.hash_receipt h
                  WHERE h.hash_kind = 'normalized_record_digest'
                    AND h.normalized_record_id = normalized.id
              )
        ) OR NOT EXISTS (
            SELECT 1
            FROM context.hash_receipt h
            JOIN context.hash_manifest manifest ON manifest.id = h.hash_manifest_id
            WHERE h.hash_kind = 'normalized_generation_manifest_digest'
              AND h.normalized_generation_id = NEW.id
              AND manifest.status = 'sealed'
              AND manifest.member_count = (
                  SELECT count(*) FROM context.normalized_record_identity normalized
                  WHERE normalized.normalized_generation_id = NEW.id
              )
        ) THEN
            RAISE EXCEPTION 'normalized generation % lacks required normalized digest receipts', NEW.id;
        END IF;
        IF EXISTS (
            SELECT 1
            FROM (VALUES ('raw_lineage_validation'), ('normalized_generation_verification')) required(kind)
            WHERE NOT EXISTS (
                SELECT 1 FROM context.reconciliation_receipt r
                WHERE r.normalized_generation_id = NEW.id
                  AND r.reconciliation_kind = required.kind
                  AND r.status = 'success'
            )
        ) THEN
            RAISE EXCEPTION 'normalized generation % lacks required successful reconciliation receipts', NEW.id;
        END IF;
        RETURN NEW;
    END IF;

    IF OLD.status = 'sealed' AND NEW.status = 'published' THEN
        IF NEW.id IS DISTINCT FROM OLD.id
           OR NEW.source_version_id IS DISTINCT FROM OLD.source_version_id
           OR NEW.raw_generation_id IS DISTINCT FROM OLD.raw_generation_id
           OR NEW.generation_ordinal IS DISTINCT FROM OLD.generation_ordinal
           OR NEW.normalizer_id IS DISTINCT FROM OLD.normalizer_id
           OR NEW.normalizer_version IS DISTINCT FROM OLD.normalizer_version
           OR NEW.sealed_at IS DISTINCT FROM OLD.sealed_at
           OR NEW.sealed_by IS DISTINCT FROM OLD.sealed_by
           OR NEW.created_at IS DISTINCT FROM OLD.created_at
           OR NEW.published_at IS NULL THEN
            RAISE EXCEPTION 'published normalized generation may only add its publication timestamp';
        END IF;
        IF EXISTS (
            SELECT 1
            FROM context.normalized_generation_publication publication
            WHERE publication.normalized_generation_id = NEW.id
        ) THEN
            RETURN NEW;
        END IF;
        RAISE EXCEPTION 'normalized generation % cannot publish without a publication receipt', NEW.id;
    END IF;

    RAISE EXCEPTION 'normalized generation lifecycle only permits open -> sealed -> published';
END;
$$;


--
-- Name: guard_normalized_publication(); Type: FUNCTION; Schema: context; Owner: -
--

CREATE FUNCTION context.guard_normalized_publication() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_generation_status TEXT;
BEGIN
    SELECT status INTO v_generation_status
    FROM context.normalized_generation
    WHERE id = NEW.normalized_generation_id
    FOR UPDATE;
    IF NOT FOUND OR v_generation_status <> 'sealed' THEN
        RAISE EXCEPTION 'normalized publication requires a sealed generation';
    END IF;
    IF NOT EXISTS (
        SELECT 1
        FROM context.activity_receipt receipt
        JOIN context.activity_execution execution ON execution.id = receipt.activity_execution_id
        JOIN context.normalized_generation generation
          ON generation.id = NEW.normalized_generation_id
        WHERE receipt.id = NEW.activity_receipt_id
          AND receipt.status = 'success'
          AND execution.activity_name = 'publish_generation_activity'
          AND execution.source_version_id = generation.source_version_id
          AND receipt.result_ref->>'ref_kind' = 'normalized_generation_publication'
          AND receipt.result_ref->>'ref_id' = NEW.id::TEXT
    ) THEN
        RAISE EXCEPTION 'normalized publication requires a successful publish_generation_activity receipt';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: guard_raw_generation_transition(); Type: FUNCTION; Schema: context; Owner: -
--

CREATE FUNCTION context.guard_raw_generation_transition() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'context'
    AS $$
BEGIN
    IF OLD.status <> 'open' OR NEW.status <> 'sealed' THEN
        RAISE EXCEPTION 'raw generation lifecycle only permits open -> sealed';
    END IF;
    IF NEW.id IS DISTINCT FROM OLD.id
       OR NEW.source_version_id IS DISTINCT FROM OLD.source_version_id
       OR NEW.generation_ordinal IS DISTINCT FROM OLD.generation_ordinal
       OR NEW.format_id IS DISTINCT FROM OLD.format_id
       OR NEW.parser_id IS DISTINCT FROM OLD.parser_id
       OR NEW.parser_version IS DISTINCT FROM OLD.parser_version
       OR NEW.extraction_bundle_object_id IS DISTINCT FROM OLD.extraction_bundle_object_id
       OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
        RAISE EXCEPTION 'sealed raw generation identity and parser provenance are immutable';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM context.raw_record_identity raw
        WHERE raw.raw_generation_id = NEW.id
    ) THEN
        RAISE EXCEPTION 'raw generation % cannot seal with zero records or envelope spans', NEW.id;
    END IF;
    IF EXISTS (
        SELECT 1
        FROM (
            SELECT record_ordinal,
                   row_number() OVER (ORDER BY record_ordinal) - 1 AS expected_ordinal
            FROM context.raw_record_identity
            WHERE raw_generation_id = NEW.id
        ) ordinals
        WHERE record_ordinal <> expected_ordinal
    ) THEN
        RAISE EXCEPTION 'raw generation % has non-contiguous record ordinals', NEW.id;
    END IF;
    PERFORM context.assert_raw_subtype_completeness(NEW.id);
    IF NOT EXISTS (SELECT 1 FROM context.hash_receipt h
                   WHERE h.hash_kind = 'context_source_fingerprint' AND h.source_version_id = NEW.source_version_id)
       OR EXISTS (SELECT 1 FROM context.raw_record_identity raw
                  WHERE raw.raw_generation_id = NEW.id
                    AND NOT EXISTS (SELECT 1 FROM context.hash_receipt h
                                    WHERE h.hash_kind = 'context_raw_record_fingerprint' AND h.raw_record_id = raw.id))
       OR NOT EXISTS (
            SELECT 1
            FROM context.hash_receipt h
            JOIN context.hash_manifest manifest ON manifest.id = h.hash_manifest_id
            WHERE h.hash_kind = 'context_raw_generation_fingerprint'
              AND h.raw_generation_id = NEW.id
              AND manifest.status = 'sealed'
              AND manifest.member_count = (
                  SELECT count(*) FROM context.raw_record_identity raw
                  WHERE raw.raw_generation_id = NEW.id
              )
       ) THEN
        RAISE EXCEPTION 'raw generation % lacks required context fingerprint receipts', NEW.id;
    END IF;
    IF EXISTS (
        SELECT 1
        FROM (VALUES ('record_accounting'), ('byte_coverage'), ('raw_source_verification')) required(kind)
        WHERE NOT EXISTS (
            SELECT 1 FROM context.reconciliation_receipt r
            WHERE r.raw_generation_id = NEW.id
              AND r.reconciliation_kind = required.kind
              AND r.status = 'success'
        )
    ) THEN
        RAISE EXCEPTION 'raw generation % lacks required successful reconciliation receipts', NEW.id;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: register_raw_format_subtype(text); Type: FUNCTION; Schema: context; Owner: -
--

CREATE FUNCTION context.register_raw_format_subtype(p_format_id text) RETURNS regclass
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'context'
    AS $_$
DECLARE
    v_table_name TEXT;
    v_relation REGCLASS;
    v_relation_kind "char";
    v_raw_record_attnum SMALLINT;
    v_raw_identity_id_attnum SMALLINT;
    v_native_fields_attnum SMALLINT;
    v_native_metadata_attnum SMALLINT;
BEGIN
    IF p_format_id !~ '^[a-z][a-z0-9_]{0,58}$' THEN
        RAISE EXCEPTION 'invalid raw format id %', p_format_id;
    END IF;

    v_table_name := 'raw_' || p_format_id;
    EXECUTE format(
        'CREATE TABLE IF NOT EXISTS context.%I (
            raw_record_id UUID PRIMARY KEY
                REFERENCES context.raw_record_identity(id) ON DELETE RESTRICT,
            native_fields JSONB NOT NULL DEFAULT ''{}''::jsonb
                CHECK (jsonb_typeof(native_fields) = ''object''),
            native_metadata JSONB NOT NULL DEFAULT ''{}''::jsonb
                CHECK (jsonb_typeof(native_metadata) = ''object''),
            created_at TIMESTAMPTZ NOT NULL DEFAULT now()
        )',
        v_table_name
    );
    v_relation := to_regclass(format('context.%I', v_table_name));

    SELECT relkind INTO v_relation_kind
    FROM pg_class
    WHERE oid = v_relation;
    IF v_relation_kind IS DISTINCT FROM 'r'::"char" THEN
        RAISE EXCEPTION 'raw subtype % must be an ordinary table, found relation kind %',
            v_relation::TEXT, v_relation_kind;
    END IF;

    SELECT attnum INTO v_raw_identity_id_attnum
    FROM pg_attribute
    WHERE attrelid = 'context.raw_record_identity'::regclass
      AND attname = 'id'
      AND atttypid = 'uuid'::regtype
      AND attnotnull
      AND NOT attisdropped;

    SELECT attnum INTO v_raw_record_attnum
    FROM pg_attribute
    WHERE attrelid = v_relation
      AND attname = 'raw_record_id'
      AND atttypid = 'uuid'::regtype
      AND attnotnull
      AND NOT attisdropped;

    IF v_raw_record_attnum IS NULL OR v_raw_identity_id_attnum IS NULL THEN
        RAISE EXCEPTION 'raw subtype % must have a NOT NULL UUID raw_record_id key column',
            v_relation::TEXT;
    END IF;
    IF NOT EXISTS (
        SELECT 1
        FROM pg_constraint
        WHERE conrelid = v_relation
          AND contype = 'p'
          AND conkey = ARRAY[v_raw_record_attnum]::SMALLINT[]
    ) THEN
        RAISE EXCEPTION 'raw subtype % must have raw_record_id as its exact primary key',
            v_relation::TEXT;
    END IF;
    IF NOT EXISTS (
        SELECT 1
        FROM pg_constraint
        WHERE conrelid = v_relation
          AND contype = 'f'
          AND confrelid = 'context.raw_record_identity'::regclass
          AND conkey = ARRAY[v_raw_record_attnum]::SMALLINT[]
          AND confkey = ARRAY[v_raw_identity_id_attnum]::SMALLINT[]
          AND confdeltype = 'r'
    ) THEN
        RAISE EXCEPTION 'raw subtype % must have an exact raw_record_id FK to context.raw_record_identity(id) ON DELETE RESTRICT',
            v_relation::TEXT;
    END IF;

    SELECT attnum INTO v_native_fields_attnum
    FROM pg_attribute
    WHERE attrelid = v_relation
      AND attname = 'native_fields'
      AND atttypid = 'jsonb'::regtype
      AND attnotnull
      AND NOT attisdropped;
    SELECT attnum INTO v_native_metadata_attnum
    FROM pg_attribute
    WHERE attrelid = v_relation
      AND attname = 'native_metadata'
      AND atttypid = 'jsonb'::regtype
      AND attnotnull
      AND NOT attisdropped;
    IF v_native_fields_attnum IS NULL OR v_native_metadata_attnum IS NULL THEN
        RAISE EXCEPTION 'raw subtype % must have NOT NULL JSONB native_fields and native_metadata columns',
            v_relation::TEXT;
    END IF;

    INSERT INTO context.raw_format_registry (format_id, subtype_relation)
    VALUES (p_format_id, v_relation)
    ON CONFLICT (format_id) DO NOTHING;
    IF (SELECT subtype_relation FROM context.raw_format_registry WHERE format_id = p_format_id)
       IS DISTINCT FROM v_relation THEN
        RAISE EXCEPTION 'raw format % is already registered to a different subtype relation', p_format_id;
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM pg_trigger
        WHERE tgrelid = v_relation
          AND tgname = 'raw_subtype_append_only'
          AND NOT tgisinternal
    ) THEN
        EXECUTE format(
            'CREATE TRIGGER raw_subtype_append_only
             BEFORE UPDATE OR DELETE ON context.%I
             FOR EACH ROW EXECUTE FUNCTION context.forbid_mutation()',
            v_table_name
        );
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM pg_trigger
        WHERE tgrelid = v_relation
          AND tgname = 'raw_subtype_open_generation_gate'
          AND NOT tgisinternal
    ) THEN
        EXECUTE format(
            'CREATE TRIGGER raw_subtype_open_generation_gate
             BEFORE INSERT ON context.%I
             FOR EACH ROW EXECUTE FUNCTION context.guard_raw_subtype_insert()',
            v_table_name
        );
    END IF;
    RETURN v_relation;
END;
$_$;


--
-- Name: seal_hash_manifest_from_receipt(); Type: FUNCTION; Schema: context; Owner: -
--

CREATE FUNCTION context.seal_hash_manifest_from_receipt() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'context'
    AS $$
BEGIN
    IF NEW.hash_kind IN ('context_raw_generation_fingerprint', 'normalized_generation_manifest_digest') THEN
        UPDATE context.hash_manifest SET status = 'sealed',
            member_count = (SELECT count(*) FROM context.hash_manifest_member WHERE hash_manifest_id = NEW.hash_manifest_id),
            sealed_hash_receipt_id = NEW.id, sealed_at = NEW.computed_at
        WHERE id = NEW.hash_manifest_id;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: chain_custody_event(); Type: FUNCTION; Schema: evidence; Owner: -
--

CREATE FUNCTION evidence.chain_custody_event() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    PERFORM pg_advisory_xact_lock(hashtextextended(NEW.source_id::text, 0));
    SELECT ce.event_digest INTO NEW.prev_event_digest
      FROM evidence.custody_event ce
     WHERE ce.source_id = NEW.source_id ORDER BY ce.seq DESC LIMIT 1;
    NEW.event_digest := digest(convert_to(
        coalesce(NEW.source_id::text,'') || '|' || coalesce(NEW.file_node_id::text,'') || '|' ||
        coalesce(NEW.evidence_hash_id::text,'') || '|' || NEW.event_type || '|' || NEW.actor || '|' ||
        to_char(NEW.occurred_at,'YYYY-MM-DD"T"HH24:MI:SS.US TZH:TZM') || '|' ||
        coalesce(NEW.detail::text,'{}') || '|' || coalesce(encode(NEW.prev_event_digest,'hex'),''),
      'UTF8'), 'sha256');
    RETURN NEW;
END $$;


--
-- Name: forbid_mutation(); Type: FUNCTION; Schema: evidence; Owner: -
--

CREATE FUNCTION evidence.forbid_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  RAISE EXCEPTION 'evidence.% is immutable (originals/append-only): % blocked (never-delete -> _stale)',
    TG_TABLE_NAME, TG_OP;
END $$;


--
-- Name: FUNCTION forbid_mutation(); Type: COMMENT; Schema: evidence; Owner: -
--

COMMENT ON FUNCTION evidence.forbid_mutation() IS 'Append-only guard for evidence tables. DEV-GATED (0031): inert unless app.evidence_live=on.';


--
-- Name: raw_no_mutate(); Type: FUNCTION; Schema: evidence; Owner: -
--

CREATE FUNCTION evidence.raw_no_mutate() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- INERT UNTIL LIVE (owner, 2026-08-01: "append only only starts once we are
  -- actually live"). During build-out the schema and parsers churn, and a hard
  -- immutability rule would force a DB rebuild for every iteration. The trigger is
  -- installed now so going live is a one-line switch rather than a migration:
  --
  --   ALTER DATABASE <db> SET app.evidence_live = 'on';
  --
  -- Until then raw behaves like an ordinary table.
  IF current_setting('app.evidence_live', true) IS DISTINCT FROM 'on' THEN
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  END IF;

  -- One exception: marking a row superseded. That is the ONLY legal mutation, and it
  -- adds a forward pointer rather than changing anything the row asserts. Everything
  -- the row claimed about the source stays exactly as written.
  IF TG_OP = 'UPDATE'
     AND OLD.superseded_by IS NULL
     AND NEW.superseded_by IS NOT NULL
     AND NEW.raw            IS NOT DISTINCT FROM OLD.raw
     AND NEW.raw_text       IS NOT DISTINCT FROM OLD.raw_text
     AND NEW.content_hash   IS NOT DISTINCT FROM OLD.content_hash
     AND NEW.source_id      IS NOT DISTINCT FROM OLD.source_id
     AND NEW.device_id      IS NOT DISTINCT FROM OLD.device_id
     AND NEW.medium         IS NOT DISTINCT FROM OLD.medium
     AND NEW.record_index   IS NOT DISTINCT FROM OLD.record_index
  THEN
    RETURN NEW;
  END IF;

  RAISE EXCEPTION USING MESSAGE =
    'evidence.' || TG_TABLE_NAME ||
    ' is append-only: raw source records are never updated or deleted '
    '(the only permitted change is setting superseded_by on a live row)';
END;
$$;


--
-- Name: source_immutable_core(); Type: FUNCTION; Schema: evidence; Owner: -
--

CREATE FUNCTION evidence.source_immutable_core() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- DEV GATE (0031): immutability armed only when the platform is live.
    -- Mirrors evidence.raw_no_mutate() (0009). Owner ruling 2026-08-24.
    IF COALESCE(current_setting('app.evidence_live', true), '') <> 'on' THEN
        IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
        RETURN NEW;
    END IF;

    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'evidence.source is write-once: DELETE blocked (never-delete -> _stale)';
    END IF;
    IF  NEW.sha256 IS DISTINCT FROM OLD.sha256
     OR NEW.md5_prefilter IS DISTINCT FROM OLD.md5_prefilter
     OR NEW.byte_size IS DISTINCT FROM OLD.byte_size
     OR NEW.mime_type IS DISTINCT FROM OLD.mime_type
     OR NEW.original_filename IS DISTINCT FROM OLD.original_filename
     OR NEW.source_type IS DISTINCT FROM OLD.source_type
     OR NEW.custodian IS DISTINCT FROM OLD.custodian
     OR NEW.acquisition_source IS DISTINCT FROM OLD.acquisition_source
     OR NEW.r2_bucket IS DISTINCT FROM OLD.r2_bucket
     OR NEW.r2_key IS DISTINCT FROM OLD.r2_key
     OR NEW.provenance_tier IS DISTINCT FROM OLD.provenance_tier
     OR NEW.hash_canon_version IS DISTINCT FROM OLD.hash_canon_version
     OR NEW.supersedes_source_id IS DISTINCT FROM OLD.supersedes_source_id
     OR NEW.original_metadata IS DISTINCT FROM OLD.original_metadata
     OR NEW.ingested_at IS DISTINCT FROM OLD.ingested_at THEN
        RAISE EXCEPTION 'evidence.source core/identity columns immutable (only lifecycle status may change)';
    END IF;
    RETURN NEW;
END $$;


--
-- Name: FUNCTION source_immutable_core(); Type: COMMENT; Schema: evidence; Owner: -
--

COMMENT ON FUNCTION evidence.source_immutable_core() IS 'Write-once guard for evidence.source. DEV-GATED (0031): inert unless app.evidence_live=on. Arm at go-live: ALTER DATABASE ai SET app.evidence_live = ''on''.';


--
-- Name: reset_test_data(text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.reset_test_data(p_confirm text) RETURNS TABLE(truncated_schema text, tables_truncated integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_schema TEXT;
  v_list   TEXT;
  v_count  INTEGER;
BEGIN
  IF p_confirm IS DISTINCT FROM 'RESET' THEN
    RAISE EXCEPTION 'refusing: call ops.reset_test_data(''RESET'') to confirm a full test-data reset';
  END IF;

  FOREACH v_schema IN ARRAY ARRAY['raw','evidence','working','context','timeline','analysis'] LOOP
    SELECT string_agg(format('%I.%I', nn.nspname, c.relname), ', '), count(*)::INTEGER
      INTO v_list, v_count
      FROM pg_class c JOIN pg_namespace nn ON nn.oid = c.relnamespace
     WHERE c.relkind = 'r' AND nn.nspname = v_schema;
    IF v_list IS NOT NULL THEN
      EXECUTE 'TRUNCATE TABLE ' || v_list || ' RESTART IDENTITY CASCADE';
    END IF;
    truncated_schema := v_schema; tables_truncated := coalesce(v_count,0);
    RETURN NEXT;
  END LOOP;

  -- canon: test traffic resets, rulings survive
  TRUNCATE TABLE canon.recompute_queue, canon.change_application,
                 canon.change_decision, canon.change_proposal
    RESTART IDENTITY CASCADE;
  truncated_schema := 'canon (proposals/decisions/applications/queue only)';
  tables_truncated := 4;
  RETURN NEXT;

  -- reset per-table generations: a fresh test run starts at generation 0
  UPDATE canon.canonical_table SET current_generation = 0;

  -- D-126 self-heal: analysis.matter_knowledge_partition and
  -- analysis.case_registry_import_receipt were just truncated above as
  -- ordinary test data. Restore the DEV sentinel identity's partition and
  -- honest dev receipt immediately so the UIW admission probe (run under
  -- PLATFORM_DEV_AUTH_BYPASS pre-launch) keeps passing after every reset
  -- with no manual step. registry.matter/court_case themselves were never
  -- truncated (outside this function's schema list); this call is a no-op
  -- there unless they were separately removed. This call is itself
  -- fail-safe: it refuses (WARNING, does nothing) the moment a real
  -- (non-placeholder) matter/court_case row exists, so it can never
  -- resurrect the DEV identity over real go-live data -- see
  -- registry.reseed_dev_case_identity()'s own header comment and
  -- docs/runbooks/go-live-case-registry.md.
  PERFORM registry.reseed_dev_case_identity();
END $$;


--
-- Name: FUNCTION reset_test_data(p_confirm text); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.reset_test_data(p_confirm text) IS 'THE reset button (D-118). Truncates test data in raw/evidence/working/context/timeline/analysis and canon traffic; preserves reference (identity is cumulative, incl. test-ingest discoveries), canon rulings, ops ledgers, public, ai. Call with ''RESET'' to confirm. This is the ONLY sanctioned purge. D-126: also self-heals the pre-launch DEV case-registry sentinel identity (analysis.matter_knowledge_partition + the honest dev receipt) via registry.reseed_dev_case_identity(), which is itself a safe no-op once real go-live identity exists.';


--
-- Name: change_log_chain(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.change_log_chain() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE prev bytea;
BEGIN
  SELECT row_hash INTO prev FROM public.change_log ORDER BY seq DESC LIMIT 1;
  NEW.prev_change_hash := prev;
  NEW.row_hash := digest(
      coalesce(NEW.table_name,'') || '|' || coalesce(NEW.record_id::text,'') || '|' ||
      coalesce(NEW.field_name,'') || '|' || NEW.action || '|' ||
      coalesce(NEW.previous_value,'') || '|' || coalesce(NEW.new_value,'') || '|' ||
      NEW.actor || '|' || NEW.change_origin || '|' || coalesce(encode(prev,'hex'),''), 'sha256');
  RETURN NEW;
END $$;


--
-- Name: forbid_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.forbid_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  RAISE EXCEPTION 'public.% is append-only: % blocked', TG_TABLE_NAME, TG_OP;
END $$;


--
-- Name: require_consolidation_verified_proof_v0049(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.require_consolidation_verified_proof_v0049() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    v_proof_kind TEXT;
    v_result TEXT;
    v_details JSONB;
BEGIN
    IF NEW.checkpoint_status <> 'verified' THEN
        RETURN NEW;
    END IF;

    SELECT receipt.proof_kind, receipt.result, receipt.details
    INTO v_proof_kind, v_result, v_details
    FROM public.platform_consolidation_proof_receipt AS receipt
    WHERE receipt.id = NEW.verified_receipt_id
      AND receipt.checkpoint_id = NEW.id
      AND NOT EXISTS (
          SELECT 1
          FROM public.platform_consolidation_proof_receipt AS successor
          WHERE successor.supersedes_receipt_id = receipt.id
      );

    IF NOT FOUND OR v_result <> 'pass' OR v_proof_kind <> NEW.required_proof_kind THEN
        RAISE EXCEPTION
            'verified consolidation checkpoint % requires its exact unsuperseded passing % receipt',
            NEW.id, NEW.required_proof_kind;
    END IF;
    IF NOT (v_details ?& ARRAY[
        'phase_key', 'relation_key', 'proof_kind', 'source_snapshot_id',
        'target_snapshot_id', 'source_snapshot_sha256', 'target_snapshot_sha256',
        'manifest_sha256', 'repository_revision'
    ])
       OR v_details->>'phase_key' IS DISTINCT FROM NEW.phase_key
       OR v_details->>'relation_key' IS DISTINCT FROM NEW.relation_key
       OR v_details->>'proof_kind' IS DISTINCT FROM NEW.required_proof_kind
       OR v_details->>'source_snapshot_id' IS DISTINCT FROM NEW.source_snapshot_id
       OR v_details->>'target_snapshot_id' IS DISTINCT FROM NEW.target_snapshot_id
       OR lower(v_details->>'source_snapshot_sha256') IS DISTINCT FROM encode(NEW.source_snapshot_sha256, 'hex')
       OR lower(v_details->>'target_snapshot_sha256') IS DISTINCT FROM encode(NEW.target_snapshot_sha256, 'hex')
       OR lower(v_details->>'manifest_sha256') IS DISTINCT FROM encode(NEW.manifest_sha256, 'hex')
       OR v_details->>'repository_revision' IS DISTINCT FROM NEW.repository_revision THEN
        RAISE EXCEPTION 'verified consolidation checkpoint % has an unbound proof receipt', NEW.id;
    END IF;
    IF NEW.required_proof_kind IN ('caller_inventory', 'zero_active_sessions')
       AND (
           NOT (v_details ?& ARRAY[
               'fence_attestation_id', 'fence_attestation_sha256', 'fence_established_at',
               'fence_valid_until'
           ])
           OR v_details->>'fence_attestation_id' IS DISTINCT FROM NEW.fence_attestation_id
           OR lower(v_details->>'fence_attestation_sha256')
              IS DISTINCT FROM encode(NEW.fence_attestation_sha256, 'hex')
           OR (v_details->>'fence_established_at')::TIMESTAMPTZ
              IS DISTINCT FROM NEW.fence_established_at
           OR (v_details->>'fence_valid_until')::TIMESTAMPTZ IS DISTINCT FROM NEW.fence_valid_until
       ) THEN
        RAISE EXCEPTION 'verified caller checkpoint % requires its exact bound fence attestation', NEW.id;
    END IF;
    BEGIN
        INSERT INTO public.platform_consolidation_receipt_claim (
            receipt_id, claim_kind, checkpoint_id
        ) VALUES (NEW.verified_receipt_id, 'verified', NEW.id);
    EXCEPTION
        WHEN unique_violation THEN
            RAISE EXCEPTION
                'receipt % already has an incompatible immutable claim', NEW.verified_receipt_id
                USING ERRCODE = '23514';
    END;
    RETURN NEW;
END
$$;


--
-- Name: reseed_dev_case_identity(); Type: FUNCTION; Schema: registry; Owner: -
--

CREATE FUNCTION registry.reseed_dev_case_identity() RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_dev_matter CONSTANT UUID := 'deadbeef-dead-beef-dead-beefdeadbeef';
  v_dev_court_case CONSTANT UUID := 'cafebabe-cafe-babe-cafe-babecafebabe';
  v_placeholder_writers CONSTANT TEXT[] := ARRAY['migration-0030','migration-0069-dev-seed'];
  v_foreign_matter_count INT;
  v_foreign_case_count INT;
BEGIN
  -- Safety backstop (D-117: "nothing about [identity] is ever
  -- auto-anything"; D-126: "no fabricated owner-approval receipt is ever
  -- written"). Only ever touch registry.matter/court_case here if every row
  -- currently present is itself placeholder data (the original
  -- migration-0030 replay, or a prior run of this same seed). The moment a
  -- real (non-placeholder) row is found, do nothing but warn loudly -- this
  -- function must never be able to clobber real case identity, including
  -- when it runs automatically from ops.reset_test_data post-go-live.
  SELECT count(*) INTO v_foreign_matter_count FROM registry.matter
   WHERE created_by <> ALL(v_placeholder_writers);
  SELECT count(*) INTO v_foreign_case_count FROM registry.court_case
   WHERE created_by <> ALL(v_placeholder_writers);
  IF v_foreign_matter_count > 0 OR v_foreign_case_count > 0 THEN
    RAISE WARNING 'registry.reseed_dev_case_identity: % non-placeholder matter row(s) and % non-placeholder court_case row(s) exist -- refusing to touch case-registry identity; this database is no longer pre-launch',
      v_foreign_matter_count, v_foreign_case_count;
    RETURN;
  END IF;

  DELETE FROM registry.court_case WHERE id <> v_dev_court_case;
  DELETE FROM registry.matter WHERE id <> v_dev_matter;

  INSERT INTO registry.matter (id, title, status, created_by, verification_state)
  VALUES (v_dev_matter, 'DEV — placeholder matter (pre-launch, disposable)', 'active',
          'migration-0069-dev-seed', 'proposed')
  ON CONFLICT (id) DO UPDATE SET
    title = EXCLUDED.title, status = EXCLUDED.status,
    created_by = EXCLUDED.created_by, verification_state = EXCLUDED.verification_state;

  INSERT INTO registry.court_case (id, matter_id, caption, status, is_primary, created_by, verification_state)
  VALUES (v_dev_court_case, v_dev_matter, 'DEV — placeholder proceeding (pre-launch, disposable)',
          'pre_filing', true, 'migration-0069-dev-seed', 'proposed')
  ON CONFLICT (id) DO UPDATE SET
    matter_id = EXCLUDED.matter_id, caption = EXCLUDED.caption, status = EXCLUDED.status,
    is_primary = EXCLUDED.is_primary, created_by = EXCLUDED.created_by,
    verification_state = EXCLUDED.verification_state;

  INSERT INTO analysis.matter_knowledge_partition (partition_key, matter_id, default_court_case_id, created_by)
  VALUES ('primary', v_dev_matter, v_dev_court_case, 'migration-0069-dev-seed')
  ON CONFLICT (partition_key) DO UPDATE SET
    matter_id = EXCLUDED.matter_id, default_court_case_id = EXCLUDED.default_court_case_id,
    created_by = EXCLUDED.created_by;

  -- No natural upsert target (id is a surrogate uuidv7()); insert only if a
  -- matching dev receipt is not already present so re-running this after a
  -- no-op reset (nothing was truncated) never raises a duplicate/unique
  -- error, and a fresh insert after a real reset (old row truncated away)
  -- always lands with the identical content values.
  INSERT INTO analysis.case_registry_import_receipt (
    manifest_sha256, source_migration_uri, source_migration_sha256, source_git_commit,
    payload_schema_version, payload_byte_length, canonical_payload_sha256, api_payload_sha256,
    source_observed_at, matter_id, court_case_id, partition_key, approved_by, approved_on, imported_by
  )
  SELECT
    decode('baadf00dbaadf00dbaadf00dbaadf00dbaadf00dbaadf00dbaadf00dbaadf00d', 'hex'),
    'sql/0069_dev_case_registry_identity.sql',
    decode('deadbeefdeadbeefdeadbeefdeadbeefdeadbeefdeadbeefdeadbeefdeadbeef', 'hex'),
    'deadbeefdeadbeefdeadbeefdeadbeefdeadbeef',
    'dev-placeholder-v1',
    1,
    decode('cafebabecafebabecafebabecafebabecafebabecafebabecafebabecafebabe', 'hex'),
    decode('deadfacedeadfacedeadfacedeadfacedeadfacedeadfacedeadfacedeadface', 'hex'),
    TIMESTAMPTZ '2026-09-02 00:00:00+00',
    v_dev_matter, v_dev_court_case, 'primary', 'dev-mode-placeholder', DATE '2026-09-02',
    'migration-0069-dev-seed'
  WHERE NOT EXISTS (
    SELECT 1 FROM analysis.case_registry_import_receipt
     WHERE matter_id = v_dev_matter AND court_case_id = v_dev_court_case
       AND approved_by = 'dev-mode-placeholder'
  );
END
$$;


--
-- Name: FUNCTION reseed_dev_case_identity(); Type: COMMENT; Schema: registry; Owner: -
--

COMMENT ON FUNCTION registry.reseed_dev_case_identity() IS 'D-126: forces the fixed DEV sentinel Matter/CourtCase identity (deadbeef.../cafebabe...) plus its knowledge partition and an honestly-labeled dev receipt (approved_by=''dev-mode-placeholder'', never ''owner''). Idempotent -- refuses (WARNING, no-op) the instant any non-placeholder matter/court_case row exists. Invoked directly by sql/0069 and automatically by ops.reset_test_data so identity self-heals across every purge/reset/re-ingest cycle with no manual re-run.';


--
-- Name: generation_supersede_only(); Type: FUNCTION; Schema: timeline; Owner: -
--

CREATE FUNCTION timeline.generation_supersede_only() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.status <> 'sealed' THEN
        RAISE EXCEPTION 'timeline_projection_generation %: already %, no further UPDATE allowed', OLD.id, OLD.status;
    END IF;
    IF NEW.status NOT IN ('superseded', 'quarantined') THEN
        RAISE EXCEPTION 'timeline_projection_generation: UPDATE must set status to superseded or quarantined';
    END IF;
    IF to_jsonb(NEW) - 'status' - 'superseded_by' IS DISTINCT FROM to_jsonb(OLD) - 'status' - 'superseded_by' THEN
        RAISE EXCEPTION 'timeline_projection_generation: only status/superseded_by may change';
    END IF;
    RETURN NEW;
END
$$;


--
-- Name: cdc_ack(text, text, bigint); Type: FUNCTION; Schema: working; Owner: -
--

CREATE FUNCTION working.cdc_ack(p_sink_id text, p_event_table text, p_last_event_id bigint) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE v_new BIGINT;
BEGIN
  IF p_last_event_id IS NULL OR p_last_event_id < 0 THEN
    RAISE EXCEPTION 'cdc_ack: p_last_event_id must be >= 0';
  END IF;
  INSERT INTO working.cdc_cursor (sink_id, source_event_table, last_event_id, last_advanced_at)
  VALUES (p_sink_id, p_event_table, p_last_event_id, now())
  ON CONFLICT (sink_id, source_event_table) DO UPDATE
    SET last_event_id    = GREATEST(working.cdc_cursor.last_event_id, EXCLUDED.last_event_id),
        last_advanced_at = now(),
        updated_at       = now()
  RETURNING last_event_id INTO v_new;
  RETURN v_new;
END;
$$;


--
-- Name: FUNCTION cdc_ack(p_sink_id text, p_event_table text, p_last_event_id bigint); Type: COMMENT; Schema: working; Owner: -
--

COMMENT ON FUNCTION working.cdc_ack(p_sink_id text, p_event_table text, p_last_event_id bigint) IS 'Monotonic, idempotent cursor advance. Safe to retry: a re-ack of an already-acked batch changes nothing (GREATEST), which is what makes the Part-2 drainer a legal Temporal Activity.';


--
-- Name: cdc_claim_batch(text, text, integer, boolean); Type: FUNCTION; Schema: working; Owner: -
--

CREATE FUNCTION working.cdc_claim_batch(p_sink_id text, p_event_table text, p_limit integer DEFAULT 100, p_allow_promotion_only boolean DEFAULT false) RETURNS TABLE(event_id bigint, operation text, source_pk uuid, row_data jsonb, source_generation bigint, occurred_at timestamp with time zone, knowledge_time timestamp with time zone, disclosure_tier text, created_at timestamp with time zone)
    LANGUAGE plpgsql
    AS $_$
DECLARE
  v_schema TEXT;
  v_promotion_only BOOLEAN;
  v_last BIGINT;
BEGIN
  IF p_limit IS NULL OR p_limit < 1 OR p_limit > 10000 THEN
    RAISE EXCEPTION 'cdc_claim_batch: p_limit must be between 1 and 10000';
  END IF;

  SELECT s.source_schema INTO v_schema FROM working.cdc_source s WHERE s.event_table = p_event_table;
  IF v_schema IS NULL THEN
    RAISE EXCEPTION 'cdc_claim_batch: % is not a registered outbox (working.cdc_source)', p_event_table;
  END IF;

  SELECT k.promotion_only INTO v_promotion_only FROM working.cdc_sink k WHERE k.sink_id = p_sink_id;
  IF v_promotion_only IS NULL THEN
    RAISE EXCEPTION 'cdc_claim_batch: % is not a registered sink (working.cdc_sink)', p_sink_id;
  END IF;
  IF v_promotion_only AND NOT p_allow_promotion_only THEN
    -- D-107: SurrealDB and any other promotion_only sink is never drained into
    -- automatically. A caller that wants to RAISE PROMOTION CANDIDATES says so.
    RAISE EXCEPTION 'cdc_claim_batch: sink % is promotion_only (D-107); pass p_allow_promotion_only => TRUE and write a promotion CANDIDATE, never the sink itself', p_sink_id;
  END IF;

  INSERT INTO working.cdc_cursor (sink_id, source_event_table)
  VALUES (p_sink_id, p_event_table)
  ON CONFLICT (sink_id, source_event_table) DO NOTHING;

  SELECT c.last_event_id INTO v_last
    FROM working.cdc_cursor c
   WHERE c.sink_id = p_sink_id AND c.source_event_table = p_event_table
     FOR UPDATE SKIP LOCKED;

  IF NOT FOUND THEN
    RETURN;   -- another worker holds this lane
  END IF;

  RETURN QUERY EXECUTE format(
    'SELECT e.event_id, e.operation, e.source_pk, e.row_data, e.source_generation,'
    ' e.occurred_at, e.knowledge_time, e.disclosure_tier, e.created_at'
    ' FROM %I.%I e WHERE e.event_id > $1 ORDER BY e.event_id LIMIT $2', v_schema, p_event_table)
  USING v_last, p_limit;
END;
$_$;


--
-- Name: FUNCTION cdc_claim_batch(p_sink_id text, p_event_table text, p_limit integer, p_allow_promotion_only boolean); Type: COMMENT; Schema: working; Owner: -
--

COMMENT ON FUNCTION working.cdc_claim_batch(p_sink_id text, p_event_table text, p_limit integer, p_allow_promotion_only boolean) IS 'Part-2 drainer entry point. Claim = FOR UPDATE SKIP LOCKED on the cursor row for the whole batch; call working.cdc_ack in the SAME transaction.';


--
-- Name: cdc_dead_letter_event(text, text, bigint, jsonb, text, text, integer); Type: FUNCTION; Schema: working; Owner: -
--

CREATE FUNCTION working.cdc_dead_letter_event(p_sink_id text, p_event_table text, p_event_id bigint, p_row_data jsonb, p_error_class text, p_error_message text, p_attempts integer) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE v_id UUID;
BEGIN
  INSERT INTO working.cdc_dead_letter
    (sink_id, source_event_table, source_event_id, row_data, error_class, error_message, attempts)
  VALUES (p_sink_id, p_event_table, p_event_id, p_row_data, p_error_class, p_error_message, p_attempts)
  ON CONFLICT (sink_id, source_event_table, source_event_id) DO UPDATE
    SET attempts = EXCLUDED.attempts, error_class = EXCLUDED.error_class,
        error_message = EXCLUDED.error_message, failed_at = now()
  RETURNING id INTO v_id;
  PERFORM working.cdc_ack(p_sink_id, p_event_table, p_event_id);
  RETURN v_id;
END;
$$;


--
-- Name: cdc_lag(); Type: FUNCTION; Schema: working; Owner: -
--

CREATE FUNCTION working.cdc_lag() RETURNS TABLE(sink_id text, source_event_table text, auto_drain boolean, promotion_only boolean, last_event_id bigint, max_event_id bigint, pending bigint, open_dead_letters bigint, last_advanced_at timestamp with time zone)
    LANGUAGE plpgsql
    AS $$
DECLARE r RECORD; v_max BIGINT;
BEGIN
  FOR r IN
    SELECT k.sink_id AS s, src.event_table AS et, src.source_schema AS sch,
           k.auto_drain AS ad, k.promotion_only AS po
      FROM working.cdc_sink k CROSS JOIN working.cdc_source src
  LOOP
    EXECUTE format('SELECT COALESCE(max(event_id),0) FROM %I.%I', r.sch, r.et) INTO v_max;
    sink_id := r.s; source_event_table := r.et; auto_drain := r.ad; promotion_only := r.po;
    last_event_id := NULL; last_advanced_at := NULL;
    SELECT c.last_event_id, c.last_advanced_at INTO last_event_id, last_advanced_at
      FROM working.cdc_cursor c WHERE c.sink_id = r.s AND c.source_event_table = r.et;
    last_event_id := COALESCE(last_event_id, 0);
    max_event_id := v_max;
    pending := GREATEST(v_max - last_event_id, 0);
    SELECT count(*) INTO open_dead_letters FROM working.cdc_dead_letter d
     WHERE d.sink_id = r.s AND d.source_event_table = r.et AND d.resolved_at IS NULL;
    RETURN NEXT;
  END LOOP;
END;
$$;


--
-- Name: FUNCTION cdc_lag(); Type: COMMENT; Schema: working; Owner: -
--

COMMENT ON FUNCTION working.cdc_lag() IS 'Operator console cdc-status source. Alert when open_dead_letters > 0 (mandatory, D-054 ruling 7) and when pending grows monotonically for an auto_drain sink.';


--
-- Name: cdc_reset_cursor(text, text, bigint); Type: FUNCTION; Schema: working; Owner: -
--

CREATE FUNCTION working.cdc_reset_cursor(p_sink_id text, p_event_table text, p_to_event_id bigint DEFAULT 0) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE v_new BIGINT;
BEGIN
  INSERT INTO working.cdc_cursor (sink_id, source_event_table, last_event_id)
  VALUES (p_sink_id, p_event_table, p_to_event_id)
  ON CONFLICT (sink_id, source_event_table) DO UPDATE
    SET last_event_id = EXCLUDED.last_event_id, updated_at = now()
  RETURNING last_event_id INTO v_new;
  RETURN v_new;
END;
$$;


