--
-- Name: derived_write_guard(); Type: FUNCTION; Schema: working; Owner: -
--

CREATE FUNCTION working.derived_write_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF current_setting('app.enforce_derived_guard', true) IS DISTINCT FROM 'on' THEN
    RETURN NEW;                      -- guard not armed
  END IF;
  IF current_setting('app.deriving', true) = 'on' THEN
    RETURN NEW;                      -- the deriver is allowed
  END IF;
  RAISE EXCEPTION USING MESSAGE =
    'analysis.' || TG_TABLE_NAME
    || ' is a DERIVED table: write it only from the derivation pass '
    || '(SET LOCAL app.deriving = ''on''). Raw is the single insert target.';
END;
$$;


--
-- Name: emit_chat_row_event(); Type: FUNCTION; Schema: working; Owner: -
--

CREATE FUNCTION working.emit_chat_row_event() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE target_table TEXT := TG_TABLE_NAME || '_event';
BEGIN
    EXECUTE format('INSERT INTO working.%I (operation, row_data) VALUES ($1, $2)', target_table)
        USING TG_OP, to_jsonb(NEW);
    PERFORM pg_notify('working_chat_changed', TG_TABLE_NAME);
    RETURN NEW;
END;
$_$;


--
-- Name: emit_row_event(); Type: FUNCTION; Schema: working; Owner: -
--

CREATE FUNCTION working.emit_row_event() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
  v_payload JSONB;
  v_channel TEXT := COALESCE(TG_ARGV[0], 'working_cdc');
  v_event_table TEXT := TG_TABLE_NAME || '_event';
BEGIN
  IF TG_OP = 'DELETE' THEN
    v_payload := to_jsonb(OLD);
  ELSE
    v_payload := to_jsonb(NEW);
  END IF;

  EXECUTE format(
    'INSERT INTO %I.%I (operation, source_pk, row_data, source_generation,'
    ' occurred_at, knowledge_time, disclosure_tier, xact_id)'
    ' VALUES ($1,$2,$3,$4,$5,$6,$7,$8)', TG_TABLE_SCHEMA, v_event_table)
  USING
    TG_OP,
    (v_payload ->> 'id')::UUID,
    v_payload,
    NULLIF(v_payload ->> 'source_generation', '')::BIGINT,
    NULLIF(v_payload ->> 'occurred_at', '')::TIMESTAMPTZ,
    NULLIF(v_payload ->> 'knowledge_time', '')::TIMESTAMPTZ,
    v_payload ->> 'disclosure_tier',
    pg_current_xact_id()::TEXT::BIGINT;

  -- NOTIFY is a WAKEUP, never the transport (ADR-0052 Part 1). Aggregate id
  -- only; the payload lives in the outbox row. A lost notification is healed
  -- by the worker timed poll -- the notification only buys latency.
  PERFORM pg_notify(v_channel, v_event_table || ':' || COALESCE(v_payload ->> 'id', ''));

  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$_$;


--
-- Name: FUNCTION emit_row_event(); Type: COMMENT; Schema: working; Owner: -
--

COMMENT ON FUNCTION working.emit_row_event() IS 'ADR-0052 D-054 ruling 4: FULL outbox row per write, trigger-written, same transaction. Supersedes the orphaned working.emit_chat_row_event() (sql/0024, never wired live), which is retained under the never-delete rule.';


--
-- Name: enqueue_evidence_vector_projection(uuid[], text); Type: FUNCTION; Schema: working; Owner: -
--

CREATE FUNCTION working.enqueue_evidence_vector_projection(p_record_ids uuid[], p_reason text) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE queued INTEGER;
BEGIN
  IF p_reason IS NULL OR length(trim(p_reason))=0 THEN
    RAISE EXCEPTION 'VECTOR_PROJECTION_REASON_REQUIRED';
  END IF;
  INSERT INTO working.evidence_vector_projection_job(chunk_id, reason)
  SELECT DISTINCT bridge.chunk_id, p_reason
    FROM working.content_chunk_message bridge
   WHERE bridge.message_id=ANY(p_record_ids)
  ON CONFLICT (chunk_id, projection_version) DO UPDATE
    SET reason=EXCLUDED.reason, status='pending', generation=working.evidence_vector_projection_job.generation+1,
        next_attempt_at=now(),
        locked_at=NULL, locked_by=NULL, completed_at=NULL, updated_at=now();
  GET DIAGNOSTICS queued = ROW_COUNT;
  RETURN queued;
END $$;


