--
-- Name: case_registry_import_receipt; Type: TABLE; Schema: analysis; Owner: -
--

CREATE TABLE analysis.case_registry_import_receipt (
    id uuid DEFAULT uuidv7() NOT NULL,
    manifest_sha256 bytea NOT NULL,
    source_migration_uri text NOT NULL,
    source_migration_sha256 bytea NOT NULL,
    source_git_commit text NOT NULL,
    payload_schema_version text NOT NULL,
    payload_byte_length bigint NOT NULL,
    canonical_payload_sha256 bytea NOT NULL,
    api_payload_sha256 bytea NOT NULL,
    source_observed_at timestamp with time zone NOT NULL,
    matter_id uuid NOT NULL,
    court_case_id uuid NOT NULL,
    partition_key text NOT NULL,
    approved_by text NOT NULL,
    approved_on date NOT NULL,
    imported_by text NOT NULL,
    imported_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT case_registry_import_receipt_api_payload_sha256_check CHECK ((octet_length(api_payload_sha256) = 32)),
    CONSTRAINT case_registry_import_receipt_approved_by_check CHECK ((length(btrim(approved_by)) > 0)),
    CONSTRAINT case_registry_import_receipt_canonical_payload_sha256_check CHECK ((octet_length(canonical_payload_sha256) = 32)),
    CONSTRAINT case_registry_import_receipt_imported_by_check CHECK ((length(btrim(imported_by)) > 0)),
    CONSTRAINT case_registry_import_receipt_manifest_sha256_check CHECK ((octet_length(manifest_sha256) = 32)),
    CONSTRAINT case_registry_import_receipt_payload_byte_length_check CHECK ((payload_byte_length > 0)),
    CONSTRAINT case_registry_import_receipt_payload_schema_version_check CHECK ((length(btrim(payload_schema_version)) > 0)),
    CONSTRAINT case_registry_import_receipt_source_git_commit_check CHECK ((source_git_commit ~ '^[0-9a-f]{40}$'::text)),
    CONSTRAINT case_registry_import_receipt_source_migration_sha256_check CHECK ((octet_length(source_migration_sha256) = 32)),
    CONSTRAINT case_registry_import_receipt_source_migration_uri_check CHECK ((length(btrim(source_migration_uri)) > 0))
);


--
-- Name: chunk_classification; Type: TABLE; Schema: analysis; Owner: -
--

CREATE TABLE analysis.chunk_classification (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    run_key text NOT NULL,
    batch_index integer NOT NULL,
    classifier_version text NOT NULL,
    conversation_key text,
    seq bigint,
    record_ref text,
    occurred_at timestamp with time zone,
    message_text text NOT NULL,
    labels text[] DEFAULT '{}'::text[] NOT NULL,
    sentiment text,
    severity integer,
    summary text,
    judge_verdict text,
    judge_confidence real,
    judge_model text,
    classify_model text,
    review_state text DEFAULT 'unreviewed'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    decision_id text,
    actor text,
    decision text,
    reason text,
    source text,
    adjudicated_at timestamp with time zone,
    CONSTRAINT chunk_classification_judge_confidence_check CHECK (((judge_confidence IS NULL) OR ((judge_confidence >= (0)::double precision) AND (judge_confidence <= (1)::double precision)))),
    CONSTRAINT chunk_classification_severity_check CHECK (((severity IS NULL) OR ((severity >= 0) AND (severity <= 10)))),
    CONSTRAINT chunkclass_adjudication_fields_complete CHECK ((((decision_id IS NULL) AND (actor IS NULL) AND (decision IS NULL) AND (reason IS NULL) AND (source IS NULL) AND (adjudicated_at IS NULL)) OR ((decision_id IS NOT NULL) AND (actor IS NOT NULL) AND (decision IS NOT NULL) AND (reason IS NOT NULL) AND (source IS NOT NULL) AND (adjudicated_at IS NOT NULL)))),
    CONSTRAINT chunkclass_decision_valid CHECK (((decision IS NULL) OR (decision = ANY (ARRAY['approve'::text, 'correct'::text]))))
);


--
-- Name: TABLE chunk_classification; Type: COMMENT; Schema: analysis; Owner: -
--

COMMENT ON TABLE analysis.chunk_classification IS 'DRAFT classification output of the n8n/Temporal pipeline (D-068). Versioned drafts only — classifier_version stamps provenance; re-runs add rows under new versions; low confidence lands as review_state=unreviewed (never a flag). No evidence-status effect.';


--
-- Name: COLUMN chunk_classification.decision_id; Type: COMMENT; Schema: analysis; Owner: -
--

COMMENT ON COLUMN analysis.chunk_classification.decision_id IS 'GAP-031: reviewer-minted idempotency key for this item''s adjudication decision. NULL for drafts never routed through the HITL review gate.';


--
-- Name: COLUMN chunk_classification.actor; Type: COMMENT; Schema: analysis; Owner: -
--

COMMENT ON COLUMN analysis.chunk_classification.actor IS 'GAP-031: reviewer identity that made this adjudication decision.';


--
-- Name: COLUMN chunk_classification.decision; Type: COMMENT; Schema: analysis; Owner: -
--

COMMENT ON COLUMN analysis.chunk_classification.decision IS 'GAP-031: normalized decision — approve or correct only (reject/pending items never reach this table).';


--
-- Name: COLUMN chunk_classification.reason; Type: COMMENT; Schema: analysis; Owner: -
--

COMMENT ON COLUMN analysis.chunk_classification.reason IS 'GAP-031: reviewer-supplied rationale for the decision. Required whenever decision_id is set.';


--
-- Name: COLUMN chunk_classification.source; Type: COMMENT; Schema: analysis; Owner: -
--

COMMENT ON COLUMN analysis.chunk_classification.source IS 'GAP-031: origin surface of the decision (e.g. workbench-ui, temporal-cli).';


--
-- Name: COLUMN chunk_classification.adjudicated_at; Type: COMMENT; Schema: analysis; Owner: -
--

COMMENT ON COLUMN analysis.chunk_classification.adjudicated_at IS 'GAP-031: when the persist activity recorded the decision (n8n now()), not when the reviewer made it in the gate — the workflow''s ItemDecisionRecord carries no timestamp today (out of this packet''s file ownership; see GAP-031-IMPLEMENTATION-STATUS.md follow-through section).';


--
-- Name: claim_assertion; Type: TABLE; Schema: analysis; Owner: -
--

CREATE TABLE analysis.claim_assertion (
    id uuid DEFAULT uuidv7() NOT NULL,
    assertion_generation smallint NOT NULL,
    assertion_kind text NOT NULL,
    statement text NOT NULL,
    rationale text NOT NULL,
    asserted_by_kind text NOT NULL,
    asserted_by text NOT NULL,
    asserted_at timestamp with time zone DEFAULT now() NOT NULL,
    salience text,
    argument_targets text[] DEFAULT '{}'::text[] NOT NULL,
    owner_disposition text DEFAULT 'unreviewed'::text NOT NULL,
    disposition_reason text,
    disposition_at timestamp with time zone,
    source_ref text,
    supersedes_id uuid,
    attrs jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT claim_assertion_asserted_by_check CHECK ((length(btrim(asserted_by)) > 0)),
    CONSTRAINT claim_assertion_asserted_by_kind_check CHECK ((asserted_by_kind = ANY (ARRAY['owner'::text, 'model'::text]))),
    CONSTRAINT claim_assertion_assertion_generation_check CHECK ((assertion_generation = ANY (ARRAY[1, 2]))),
    CONSTRAINT claim_assertion_assertion_kind_check CHECK ((assertion_kind = ANY (ARRAY['connection'::text, 'significance'::text, 'decision'::text, 'exposure'::text, 'gap'::text, 'correction'::text]))),
    CONSTRAINT claim_assertion_attrs_check CHECK ((jsonb_typeof(attrs) = 'object'::text)),
    CONSTRAINT claim_assertion_disposition_dated CHECK (((owner_disposition = 'unreviewed'::text) OR (disposition_at IS NOT NULL))),
    CONSTRAINT claim_assertion_no_self_supersede CHECK ((supersedes_id IS DISTINCT FROM id)),
    CONSTRAINT claim_assertion_owner_disposition_check CHECK ((owner_disposition = ANY (ARRAY['unreviewed'::text, 'accepted'::text, 'rejected'::text, 'parked'::text, 'superseded'::text]))),
    CONSTRAINT claim_assertion_parked_has_reason CHECK (((owner_disposition <> 'parked'::text) OR (disposition_reason IS NOT NULL))),
    CONSTRAINT claim_assertion_rationale_check CHECK ((length(btrim(rationale)) > 0)),
    CONSTRAINT claim_assertion_salience_check CHECK (((salience IS NULL) OR (salience = ANY (ARRAY['hot'::text, 'good'::text, 'warm'::text])))),
    CONSTRAINT claim_assertion_statement_check CHECK ((length(btrim(statement)) > 0))
);


