    CONSTRAINT claim_assertion_synthesis_member_member_ordinal_check CHECK ((member_ordinal >= 0)),
    CONSTRAINT synthesis_divergence_is_explained CHECK (((agreement_state <> 'diverges'::text) OR (divergence_note IS NOT NULL))),
