    run_id uuid NOT NULL,
    stage_id text NOT NULL,
    stage_version text NOT NULL,
    manifest_id uuid NOT NULL,
    manifest_digest bytea NOT NULL,
    semantica_receipt_id uuid,
    sat_temporal_receipt_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE graphrag_comparison_join; Type: COMMENT; Schema: analysis; Owner: -
--

COMMENT ON TABLE analysis.graphrag_comparison_join IS 'Joins the two lane receipts for one stage. Both lanes must cite the same manifest_digest; no automatic fusion of results (D-093).';


--
-- Name: graphrag_comparison_run; Type: TABLE; Schema: analysis; Owner: -
--

CREATE TABLE analysis.graphrag_comparison_run (
    id uuid DEFAULT uuidv7() NOT NULL,
    query_reference text NOT NULL,
    correlation_id text,
    requested_mode text NOT NULL,
    case_compatibility_reference text,
    horizon_at timestamp with time zone NOT NULL,
    created_by text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE graphrag_comparison_run; Type: COMMENT; Schema: analysis; Owner: -
--

COMMENT ON TABLE analysis.graphrag_comparison_run IS 'D-093 side-by-side evaluation run. horizon_at pins the pre-ranking horizon boundary both lanes share.';


--
-- Name: graphrag_eligibility_manifest; Type: TABLE; Schema: analysis; Owner: -
--

CREATE TABLE analysis.graphrag_eligibility_manifest (
    id uuid DEFAULT uuidv7() NOT NULL,
    run_id uuid NOT NULL,
    schema_version integer DEFAULT 1 NOT NULL,
    pg_generation_reference text NOT NULL,
    source_availability_policy_version text CONSTRAINT graphrag_eligibility_manife_source_availability_policy_not_null NOT NULL,
    disclosure_policy_version text CONSTRAINT graphrag_eligibility_manifes_disclosure_policy_version_not_null NOT NULL,
    authorization_policy_version text CONSTRAINT graphrag_eligibility_manife_authorization_policy_versi_not_null NOT NULL,
    issuer text NOT NULL,
    status text DEFAULT 'open'::text NOT NULL,
    membership_digest bytea,
    member_count integer,
    sealed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT graphrag_eligibility_manifest_status_check CHECK ((status = ANY (ARRAY['open'::text, 'sealed'::text])))
);


--
-- Name: TABLE graphrag_eligibility_manifest; Type: COMMENT; Schema: analysis; Owner: -
--

COMMENT ON TABLE analysis.graphrag_eligibility_manifest IS 'The single PostgreSQL-authorized eligibility set both lanes receive. Sealing computes membership_digest; both lanes cite the same digest or the comparison is invalid.';


--
-- Name: graphrag_eligibility_manifest_member; Type: TABLE; Schema: analysis; Owner: -
--

CREATE TABLE analysis.graphrag_eligibility_manifest_member (
    manifest_id uuid NOT NULL,
    ordinal bigint NOT NULL,
    source_version_id uuid NOT NULL,
    normalized_record_id uuid CONSTRAINT graphrag_eligibility_manifest_mem_normalized_record_id_not_null NOT NULL,
    text_unit_id uuid,
    source_sha256 bytea,
    normalized_record_digest bytea,
    source_available_from timestamp with time zone,
    disclosure_tier text,
    authority_class text,
    projection_version text,
    source_provenance_ref jsonb,
    CONSTRAINT graphrag_eligibility_manifest_me_normalized_record_digest_check CHECK (((normalized_record_digest IS NULL) OR (octet_length(normalized_record_digest) = 32))),
    CONSTRAINT graphrag_eligibility_manifest_member_ordinal_check CHECK ((ordinal >= 0)),
    CONSTRAINT graphrag_eligibility_manifest_member_source_sha256_check CHECK (((source_sha256 IS NULL) OR (octet_length(source_sha256) = 32)))
);


--
-- Name: graphrag_lane_candidate; Type: TABLE; Schema: analysis; Owner: -
