    CONSTRAINT graphrag_lane_candidate_ordinal_check CHECK ((ordinal >= 0)),
    CONSTRAINT graphrag_lane_candidate_source_sha256_check CHECK (((source_sha256 IS NULL) OR (octet_length(source_sha256) = 32)))
);


--
-- Name: TABLE graphrag_lane_candidate; Type: COMMENT; Schema: analysis; Owner: -
--

COMMENT ON TABLE analysis.graphrag_lane_candidate IS 'Per-lane candidates carrying the PG source coordinate (source_version_id, normalized_record_id, text_unit_id) so two lanes can be diffed on provenance without first resolving entity identity.';


