    CONSTRAINT knowledge_evidence_promotion_idempotency_key_check CHECK (((length(btrim(idempotency_key)) >= 1) AND (length(btrim(idempotency_key)) <= 200))),
    CONSTRAINT knowledge_evidence_promotion_knowledge_lane_check CHECK ((knowledge_lane = 'evidence'::text)),
    CONSTRAINT knowledge_evidence_promotion_promoted_by_check CHECK ((length(btrim(promoted_by)) > 0)),
