    evidence_item_ids uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    normalized_record_ids uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    mcl_factors ai.mcl_factor[] DEFAULT '{}'::ai.mcl_factor[] NOT NULL,
