    CONSTRAINT legaltl_legal_gate CHECK (((safe_for_legal_use = false) OR (review_status = 'approved'::ai.review_state)))
);


--
-- Name: location_assertion; Type: TABLE; Schema: analysis; Owner: -
--

CREATE TABLE analysis.location_assertion (
