    location_id uuid,
    primary_geo ai.geo_point,
    is_conflicted boolean DEFAULT false NOT NULL,
    requires_human_review boolean DEFAULT false NOT NULL,
    safe_for_legal_use boolean DEFAULT false NOT NULL,
    reviewed_by text,
    reviewed_at timestamp with time zone,
    conduct_party ai.conduct_party,
    mcl_relevance ai.mcl_factor[] DEFAULT '{}'::ai.mcl_factor[] NOT NULL,
    source_artifact_id uuid,
    primary_record_id uuid,
    ingest_run_id uuid,
    derived_from uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    prompt_version text,
    ontology_version text,
    schema_version text,
    attrs jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: evidence_item; Type: TABLE; Schema: evidence; Owner: -
--

CREATE TABLE evidence.evidence_item (
    id uuid DEFAULT uuidv7() NOT NULL,
    case_id uuid NOT NULL,
    source_id uuid,
    file_node_id uuid,
    normalized_record_id uuid,
    evidence_hash_id uuid,
    exhibit_number text,
    title text NOT NULL,
    description text,
    quote text,
    context text,
    evidence_type text DEFAULT 'communication'::text NOT NULL,
    evidence_date timestamp with time zone,
    evidence_date_end timestamp with time zone,
    date_precision ai.precision_class DEFAULT 'exact'::ai.precision_class NOT NULL,
    assertion_type ai.assertion_type DEFAULT 'extracted_fact'::ai.assertion_type NOT NULL,
    confidence ai.confidence,
    confidence_tier text DEFAULT 'low'::text NOT NULL,
    relevance_score ai.confidence,
    is_hypothesis boolean DEFAULT false NOT NULL,
    is_exhibit boolean DEFAULT false NOT NULL,
    is_authenticated boolean DEFAULT false NOT NULL,
    authentication_method text,
    chain_of_custody text,
    sensitivity_tier ai.sensitivity_tier DEFAULT 'restricted'::ai.sensitivity_tier NOT NULL,
    privacy_sensitivity text DEFAULT 'none'::text NOT NULL,
    redaction_status text DEFAULT 'none'::text NOT NULL,
    review_status ai.review_state DEFAULT 'unreviewed'::ai.review_state NOT NULL,
    reviewed_by text,
    reviewed_at timestamp with time zone,
    hitl_required boolean DEFAULT true NOT NULL,
    safe_for_legal_use boolean DEFAULT false NOT NULL,
    supersedes_item_id uuid,
    source_run_id uuid,
    prompt_version text,
    ontology_version text,
    schema_version text,
    created_by text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    matter_id uuid,
    court_case_id uuid,
    CONSTRAINT evidence_item_authentication_method_check CHECK (((authentication_method IS NULL) OR (authentication_method = ANY (ARRAY['witness_with_knowledge'::text, 'distinctive_characteristics'::text, 'process_or_system'::text, 'public_record'::text, 'hash_chain_of_custody'::text, 'self_authenticating'::text, 'stipulation'::text])))),
    CONSTRAINT evidence_item_case_management_scope_ck CHECK (((matter_id IS NULL) = (court_case_id IS NULL))),
    CONSTRAINT evidence_item_conf_tier_ck CHECK (((confidence_tier <> 'high'::text) OR (confidence IS NULL) OR ((confidence)::numeric >= 0.60))),
    CONSTRAINT evidence_item_confidence_tier_check CHECK ((confidence_tier = ANY (ARRAY['high'::text, 'medium'::text, 'low'::text]))),
    CONSTRAINT evidence_item_evidence_type_check CHECK ((evidence_type = ANY (ARRAY['communication'::text, 'document'::text, 'photo'::text, 'record'::text, 'media'::text, 'screenshot'::text, 'transcript'::text, 'metadata'::text, 'other'::text]))),
    CONSTRAINT evidence_item_privacy_sensitivity_check CHECK ((privacy_sensitivity = ANY (ARRAY['none'::text, 'pii'::text, 'minor'::text, 'sensitive_pii'::text]))),
    CONSTRAINT evidence_item_redaction_status_check CHECK ((redaction_status = ANY (ARRAY['none'::text, 'required'::text, 'applied'::text]))),
    CONSTRAINT evidence_item_safe_ck CHECK (((safe_for_legal_use = false) OR ((review_status = 'approved'::ai.review_state) AND (is_authenticated = true) AND (is_hypothesis = false) AND (redaction_status <> 'required'::text))))
);


--
-- Name: TABLE evidence_item; Type: COMMENT; Schema: evidence; Owner: -
--

COMMENT ON TABLE evidence.evidence_item IS 'THE promotion target. A row here is promoted evidence: exhibit_number, is_authenticated, chain_of_custody, safe_for_legal_use, anchored to raw via evidence_hash_id/normalized_record_id. Written only via a canon.change_proposal of kind promote, after owner ruling. Part of the litigation loop: finding -> evidence_task -> evidence_item -> factor_citation -> legal_timeline_event.';


--
-- Name: COLUMN evidence_item.matter_id; Type: COMMENT; Schema: evidence; Owner: -
--

COMMENT ON COLUMN evidence.evidence_item.matter_id IS 'Explicit case-management Matter scope. Nullable for legacy rows; promotion writes both matter_id and court_case_id.';


--
-- Name: COLUMN evidence_item.court_case_id; Type: COMMENT; Schema: evidence; Owner: -
--

COMMENT ON COLUMN evidence.evidence_item.court_case_id IS 'Explicit CourtCase scope. Nullable for legacy rows. This does not replace the historical evidence_item.case_id UUID column.';


--
-- Name: vw_court_export; Type: VIEW; Schema: analysis; Owner: -
--

CREATE VIEW analysis.vw_court_export AS
 SELECT id,
    case_id,
    exhibit_number,
    title,
    description,
    quote,
    context,
    evidence_type,
    evidence_date,
    date_precision,
    assertion_type,
    confidence,
    confidence_tier,
    is_authenticated,
    authentication_method,
    chain_of_custody,
    sensitivity_tier,
    redaction_status,
    source_id,
    file_node_id,
    evidence_hash_id,
    reviewed_by,
    reviewed_at
   FROM evidence.evidence_item ei
  WHERE ((safe_for_legal_use = true) AND (review_status = 'approved'::ai.review_state) AND (confidence_tier = ANY (ARRAY['high'::text, 'medium'::text])) AND (is_hypothesis = false) AND (is_authenticated = true) AND (redaction_status <> 'required'::text) AND (sensitivity_tier <> 'sealed'::ai.sensitivity_tier));


--
-- Name: human_label; Type: TABLE; Schema: reference; Owner: -
--

CREATE TABLE reference.human_label (
    conversation_key text NOT NULL,
    seq bigint NOT NULL,
    occurred_at timestamp with time zone,
    who text,
    message_text text NOT NULL,
    labels text[] DEFAULT '{}'::text[] NOT NULL,
    is_clean boolean,
    severity integer,
    notes text,
    CONSTRAINT human_label_severity_check CHECK (((severity IS NULL) OR ((severity >= 0) AND (severity <= 10))))
);


--
-- Name: TABLE human_label; Type: COMMENT; Schema: reference; Owner: -
--

COMMENT ON TABLE reference.human_label IS 'Prompt-example set: labeled messages for few-shot prompting / model training. Deliberately UNLINKED from live tables (owner ruling 2026-08-24 — linking caused problems every test). Stripped to message+label essentials by 0032; full-fidelity pre-strip copy = reference.human_label_gold.';


--
-- Name: vw_human_label_long; Type: VIEW; Schema: analysis; Owner: -
--

CREATE VIEW analysis.vw_human_label_long AS
 SELECT conversation_key,
    seq,
    occurred_at,
    who,
    message_text,
    unnest(labels) AS label,
    is_clean,
    severity,
    notes
   FROM reference.human_label
  WHERE (cardinality(labels) > 0);


--
-- Name: vw_labeling_progress; Type: VIEW; Schema: analysis; Owner: -
--

CREATE VIEW analysis.vw_labeling_progress AS
 SELECT count(*) AS total_messages,
    count(*) FILTER (WHERE ((cardinality(labels) > 0) OR is_clean)) AS labeled,
    count(*) FILTER (WHERE (cardinality(labels) > 0)) AS labeled_with_behavior,
    count(*) FILTER (WHERE is_clean) AS marked_clean,
    count(*) FILTER (WHERE ((cardinality(labels) = 0) AND (is_clean IS NOT TRUE))) AS remaining,
    round(((100.0 * (count(*) FILTER (WHERE ((cardinality(labels) > 0) OR is_clean)))::numeric) / (NULLIF(count(*), 0))::numeric), 1) AS pct_done
   FROM reference.human_label;


--
-- Name: message; Type: TABLE; Schema: working; Owner: -
--

CREATE TABLE working.message (
    id uuid NOT NULL,
    conversation_id uuid NOT NULL,
    ts_utc timestamp with time zone,
    platform text NOT NULL,
    external_id text,
    serial_number bigint NOT NULL,
    prev_message_id uuid,
    next_message_id uuid,
    time_since_prev_s integer,
    sender_raw text,
    sender_e164 text,
    sender_entity_id uuid,
    recipient_raw text,
    recipient_e164 text,
    direction text,
    message_type text DEFAULT 'text'::text NOT NULL,
    delivery_status text,
    status_code integer,
    is_blocked boolean DEFAULT false NOT NULL,
    raw_ts text,
    tz text,
    ts_earliest timestamp with time zone,
    ts_latest timestamp with time zone,
    temporal_confidence ai.confidence,
    relative_time_refs jsonb DEFAULT '[]'::jsonb NOT NULL,
    word_count integer,
    char_count integer,
    content_sha256 bytea,
    language text,
    surface_sentiment_hint text,
    inferred_intent_hint text,
    topic_hint text,
    domain_type_hint text,
    relevance_hint text,
    custody_relevance_hint text,
    evidence_strength_hint ai.strength_class,
    extraction_confidence ai.confidence,
    is_private boolean DEFAULT false NOT NULL,
    is_redacted boolean DEFAULT false NOT NULL,
    has_attachments boolean DEFAULT false NOT NULL,
    attachment_count integer DEFAULT 0 NOT NULL,
    has_behaviors boolean DEFAULT false NOT NULL,
    behavior_count integer DEFAULT 0 NOT NULL,
    max_behavior_severity text,
    screenshot_attachment_id uuid,
    body_embedding_ref text,
    platform_attrs jsonb DEFAULT '{}'::jsonb NOT NULL,
    raw_data jsonb,
    is_read boolean,
    hint_provenance jsonb,
    derived_from_record_id uuid,
    derived_from_raw_table text,
    derived_from_raw_id uuid,
    deriver_version text,
    derived_at timestamp with time zone,
    projection_kind text DEFAULT 'first_party'::text NOT NULL,
    CONSTRAINT message_content_sha256_check CHECK (((content_sha256 IS NULL) OR (octet_length(content_sha256) = 32))),
    CONSTRAINT message_direction_check CHECK ((direction = ANY (ARRAY['inbound'::text, 'outbound'::text, 'unknown'::text]))),
    CONSTRAINT message_projection_kind_ck CHECK ((projection_kind = 'first_party'::text))
);


--
-- Name: COLUMN message.is_read; Type: COMMENT; Schema: working; Owner: -
--

COMMENT ON COLUMN working.message.is_read IS 'SMS/MMS read flag (SBV read=1/0; iMessage is_read). NULL = unknown/not-applicable.';


--
-- Name: COLUMN message.hint_provenance; Type: COMMENT; Schema: working; Owner: -
--

COMMENT ON COLUMN working.message.hint_provenance IS 'Provenance for the *_hint columns: {field: {model, at, method, reasoning}}. A model-assigned hint that cannot say why/when/what-model is not court-usable; this records it. NULL until any hint is set by an analysis pass.';


--
-- Name: vw_message_behavior; Type: VIEW; Schema: analysis; Owner: -
--

CREATE VIEW analysis.vw_message_behavior AS
 SELECT m.id AS message_id,
    m.conversation_id,
    m.ts_utc,
    m.direction,
    m.has_behaviors,
    m.behavior_count,
    m.max_behavior_severity,
    count(pf.*) AS finding_count,
    count(pf.*) FILTER (WHERE (pf.review_status = 'approved'::ai.review_state)) AS confirmed_count,
    bool_or((pf.category_id OPERATOR(ai.=) 'threats'::ai.citext)) AS flag_threat_hypothesis,
    bool_or(((pf.category_id OPERATOR(ai.=) 'threats'::ai.citext) AND (pf.review_status = 'approved'::ai.review_state))) AS flag_threat_confirmed,
    bool_or((pf.category_id OPERATOR(ai.=) 'gaslighting'::ai.citext)) AS flag_gaslighting_hypothesis,
    bool_or((pf.category_id OPERATOR(ai.=) 'minimizing'::ai.citext)) AS flag_minimizing_hypothesis,
    bool_or((pf.category_id OPERATOR(ai.=) 'blame_shifting'::ai.citext)) AS flag_blame_hypothesis,
    array_agg(DISTINCT pf.category_id) FILTER (WHERE (pf.category_id IS NOT NULL)) AS categories
   FROM (working.message m
     LEFT JOIN analysis.pattern_finding pf ON (((pf.subject_id = m.id) AND (pf.subject_type = 'message'::text))))
  GROUP BY m.id, m.conversation_id, m.ts_utc, m.direction, m.has_behaviors, m.behavior_count, m.max_behavior_severity;


--
-- Name: VIEW vw_message_behavior; Type: COMMENT; Schema: analysis; Owner: -
--

COMMENT ON VIEW analysis.vw_message_behavior IS 'One-click behavior filters for UI. *_hypothesis = a finding exists (unreviewed OK); *_confirmed = human-approved only. Replaces the old containsThreat/Blame booleans WITHOUT bypassing the court-safety review gate.';


--
-- Name: vw_open_tasks; Type: VIEW; Schema: analysis; Owner: -
--

CREATE VIEW analysis.vw_open_tasks AS
 SELECT id,
    task_key,
    case_id,
    status,
    priority,
    priority_score,
    due_date,
    due_basis,
    human_action,
    human_action_kind,
    label_sensitivity,
    hitl_required,
    hitl_status,
    confidence_tier,
    is_hypothesis,
    ( SELECT count(*) AS count
           FROM analysis.task_dependency d
          WHERE ((d.depends_on = t.id) AND (d.dep_kind = ANY (ARRAY['blocks'::text, 'prereq_of'::text])))) AS blocks_n,
    ( SELECT e.to_status
           FROM analysis.task_event e
          WHERE (e.task_id = t.id)
          ORDER BY e.ts DESC
         LIMIT 1) AS last_event
   FROM analysis.evidence_task t
  WHERE (status <> ALL (ARRAY['closed_satisfied'::text, 'closed_unmet'::text, 'closed_overcome'::text, 'superseded'::text, 'archived'::text]))
  ORDER BY priority, priority_score DESC NULLS LAST, due_date;


--
-- Name: workflow_run; Type: TABLE; Schema: analysis; Owner: -
--

CREATE TABLE analysis.workflow_run (
    run_id uuid DEFAULT uuidv7() NOT NULL,
    workflow text NOT NULL,
    mode text DEFAULT 'auto'::text NOT NULL,
    source_name text,
    source_path text,
    sha256 text,
    artifact_id text,
    domain text,
    status text DEFAULT 'running'::text NOT NULL,
    summary jsonb,
    error text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    gate_state text,
    parent_run_id uuid,
    custody_tier text DEFAULT 'full'::text NOT NULL,
    CONSTRAINT workflow_run_custody_tier_check CHECK ((custody_tier = ANY (ARRAY['full'::text, 'light'::text]))),
    CONSTRAINT workflow_run_gate_state_check CHECK (((gate_state = ANY (ARRAY['waiting'::text, 'released'::text, 'abort'::text])) OR (gate_state IS NULL))),
    CONSTRAINT workflow_run_mode_check CHECK ((mode = ANY (ARRAY['auto'::text, 'supervised'::text]))),
    CONSTRAINT workflow_run_status_check CHECK ((status = ANY (ARRAY['running'::text, 'paused'::text, 'completed'::text, 'failed'::text])))
);


--
-- Name: workflow_run_stage; Type: TABLE; Schema: analysis; Owner: -
--

CREATE TABLE analysis.workflow_run_stage (
    stage_id bigint NOT NULL,
    run_id uuid NOT NULL,
    seq integer NOT NULL,
    name text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    content text,
    output jsonb,
    started_at timestamp with time zone,
    finished_at timestamp with time zone,
    CONSTRAINT workflow_run_stage_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'running'::text, 'success'::text, 'failed'::text, 'skipped'::text])))
);


--
-- Name: workflow_run_stage_stage_id_seq; Type: SEQUENCE; Schema: analysis; Owner: -
--

ALTER TABLE analysis.workflow_run_stage ALTER COLUMN stage_id ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME analysis.workflow_run_stage_stage_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: canonical_table; Type: TABLE; Schema: canon; Owner: -
--

CREATE TABLE canon.canonical_table (
    id uuid DEFAULT uuidv7() NOT NULL,
    table_schema text NOT NULL,
    table_name text NOT NULL,
    default_tier text DEFAULT 'batch_review'::text NOT NULL,
    current_generation bigint DEFAULT 0 NOT NULL,
    recompute_targets text[] DEFAULT '{}'::text[] NOT NULL,
    registered_by text NOT NULL,
    registered_at timestamp with time zone DEFAULT now() NOT NULL,
    notes text,
    auto_confirm_min_confidence ai.confidence
);


--
-- Name: TABLE canonical_table; Type: COMMENT; Schema: canon; Owner: -
--

COMMENT ON TABLE canon.canonical_table IS 'The canon boundary. The spine accepts proposals only against rows of tables registered here. Registration is an owner act. current_generation is the per-table staleness anchor: proposals record it at filing, adoption checks it.';


--
-- Name: COLUMN canonical_table.auto_confirm_min_confidence; Type: COMMENT; Schema: canon; Owner: -
--

COMMENT ON COLUMN canon.canonical_table.auto_confirm_min_confidence IS 'Proposals at or above this confidence route to auto_adopt (applied immediately, logged, reversible). Below it — or NULL — they wait in the table''s default tier. NULL = never auto, regardless of confidence.';


--
-- Name: change_application; Type: TABLE; Schema: canon; Owner: -
--

CREATE TABLE canon.change_application (
    id uuid DEFAULT uuidv7() NOT NULL,
    proposal_id uuid NOT NULL,
    decision_id uuid NOT NULL,
    prior_values jsonb NOT NULL,
    applied_patch jsonb NOT NULL,
    generation_before bigint NOT NULL,
    generation_after bigint NOT NULL,
    applied_at timestamp with time zone DEFAULT now() NOT NULL,
    error text
);


--
-- Name: TABLE change_application; Type: COMMENT; Schema: canon; Owner: -
--

COMMENT ON TABLE canon.change_application IS 'The receipt. prior_values preserves what canon said before the change, so no correction ever silently destroys the original reading — history by recording, not by immutability guards (D-110).';


--
-- Name: change_decision; Type: TABLE; Schema: canon; Owner: -
--

CREATE TABLE canon.change_decision (
    id uuid DEFAULT uuidv7() NOT NULL,
    proposal_id uuid NOT NULL,
    decided_by text NOT NULL,
    decision text NOT NULL,
    batch_id uuid,
    note text,
    decided_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT change_decision_decision_check CHECK ((decision = ANY (ARRAY['approve'::text, 'reject'::text, 'requeue'::text])))
);


--
-- Name: change_proposal; Type: TABLE; Schema: canon; Owner: -
--

CREATE TABLE canon.change_proposal (
    id uuid DEFAULT uuidv7() NOT NULL,
    canonical_table_id uuid NOT NULL,
    target_pk jsonb NOT NULL,
    proposal_kind text NOT NULL,
    patch jsonb NOT NULL,
    rationale text,
    origin_surface text NOT NULL,
    origin_ref jsonb DEFAULT '{}'::jsonb NOT NULL,
    proposed_by text NOT NULL,
    source_generation bigint NOT NULL,
    tier text NOT NULL,
    status text DEFAULT 'proposed'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT change_proposal_origin_surface_check CHECK ((origin_surface = ANY (ARRAY['extractor'::text, 'workbench'::text, 'graph_reconciliation'::text, 'agent'::text, 'human'::text]))),
    CONSTRAINT change_proposal_proposal_kind_check CHECK ((proposal_kind = ANY (ARRAY['correct'::text, 'adopt_candidate'::text, 'promote'::text, 'merge'::text, 'retire'::text, 'create'::text]))),
    CONSTRAINT change_proposal_status_check CHECK ((status = ANY (ARRAY['proposed'::text, 'approved'::text, 'rejected'::text, 'stale_requeued'::text, 'applied'::text, 'failed'::text])))
);


--
-- Name: TABLE change_proposal; Type: COMMENT; Schema: canon; Owner: -
--

COMMENT ON TABLE canon.change_proposal IS 'The universal write path to canon. Nothing authors canonical rows directly: extractors, the Workbench, graph reconciliation, agents and humans all file here. Rejected proposals are retained and marked, never deleted.';


--
-- Name: change_tier; Type: TABLE; Schema: canon; Owner: -
--

CREATE TABLE canon.change_tier (
    tier text NOT NULL,
    description text NOT NULL,
    auto_applies boolean DEFAULT false NOT NULL,
    sort_order integer DEFAULT 0 NOT NULL
);


--
-- Name: recompute_queue; Type: TABLE; Schema: canon; Owner: -
--

CREATE TABLE canon.recompute_queue (
    id uuid DEFAULT uuidv7() NOT NULL,
    application_id uuid NOT NULL,
    canonical_table_id uuid NOT NULL,
    target_pk jsonb NOT NULL,
    recompute_target text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    claimed_by text,
    claimed_at timestamp with time zone,
    finished_at timestamp with time zone,
    error text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT recompute_queue_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'claimed'::text, 'done'::text, 'failed'::text, 'skipped'::text])))
);


--
-- Name: TABLE recompute_queue; Type: COMMENT; Schema: canon; Owner: -
--

COMMENT ON TABLE canon.recompute_queue IS 'One row per (applied change x downstream target). Consumers poll their target, mark claimed/done. This is the leg that forces derived work to recalculate after re-canonicalization. It ships with the spine so it cannot become another consumer-less outbox.';


--
-- Name: activity_execution; Type: TABLE; Schema: context; Owner: -
--

CREATE TABLE context.activity_execution (
    id uuid DEFAULT uuidv7() NOT NULL,
    source_version_id uuid NOT NULL,
    workflow_id text NOT NULL,
    activity_name text NOT NULL,
    idempotency_key text NOT NULL,
    request_digest bytea,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT activity_execution_activity_name_check CHECK ((length(btrim(activity_name)) > 0)),
    CONSTRAINT activity_execution_idempotency_key_check CHECK ((length(btrim(idempotency_key)) > 0)),
    CONSTRAINT activity_execution_request_digest_check CHECK (((request_digest IS NULL) OR (octet_length(request_digest) = 32))),
    CONSTRAINT activity_execution_workflow_id_check CHECK ((length(btrim(workflow_id)) > 0))
);


--
-- Name: activity_receipt; Type: TABLE; Schema: context; Owner: -
--

CREATE TABLE context.activity_receipt (
    id uuid DEFAULT uuidv7() NOT NULL,
    activity_execution_id uuid NOT NULL,
    attempt integer NOT NULL,
    status text NOT NULL,
    started_at timestamp with time zone NOT NULL,
    completed_at timestamp with time zone,
    result_ref jsonb,
    error_detail jsonb,
    not_applicable_reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT activity_receipt_attempt_check CHECK ((attempt > 0)),
    CONSTRAINT activity_receipt_check CHECK ((((status = 'success'::text) AND (completed_at IS NOT NULL) AND (result_ref IS NOT NULL) AND (error_detail IS NULL) AND (not_applicable_reason IS NULL)) OR ((status = 'failed'::text) AND (completed_at IS NOT NULL) AND (result_ref IS NULL) AND (error_detail IS NOT NULL) AND (not_applicable_reason IS NULL)) OR ((status = 'not_applicable'::text) AND (completed_at IS NOT NULL) AND (result_ref IS NULL) AND (error_detail IS NULL) AND (not_applicable_reason IS NOT NULL)))),
    CONSTRAINT activity_receipt_error_detail_check CHECK (((error_detail IS NULL) OR (jsonb_typeof(error_detail) = 'object'::text))),
    CONSTRAINT activity_receipt_not_applicable_reason_check CHECK (((not_applicable_reason IS NULL) OR (length(btrim(not_applicable_reason)) > 0))),
    CONSTRAINT activity_receipt_result_ref_check CHECK (((result_ref IS NULL) OR (jsonb_typeof(result_ref) = 'object'::text))),
    CONSTRAINT activity_receipt_status_check CHECK ((status = ANY (ARRAY['success'::text, 'failed'::text, 'not_applicable'::text])))
);


--
-- Name: first_party_thread_message_relative_time_anchor; Type: TABLE; Schema: context; Owner: -
--

CREATE TABLE context.first_party_thread_message_relative_time_anchor (
    anchor_id uuid CONSTRAINT first_party_thread_message_relative_time_anc_anchor_id_not_null NOT NULL,
    thread_version_id uuid CONSTRAINT first_party_thread_message_relative__thread_version_id_not_null NOT NULL,
    message_id uuid CONSTRAINT first_party_thread_message_relative_time_an_message_id_not_null NOT NULL,
    link_role text CONSTRAINT first_party_thread_message_relative_time_anc_link_role_not_null NOT NULL,
    created_at timestamp with time zone DEFAULT now() CONSTRAINT first_party_thread_message_relative_time_an_created_at_not_null NOT NULL,
    CONSTRAINT first_party_thread_message_relative_time_anchor_link_role_check CHECK ((link_role = ANY (ARRAY['primary_fallback'::text, 'lower_bound'::text, 'upper_bound'::text, 'sequence_context'::text])))
);


--
-- Name: first_party_thread_source_relative_time_anchor; Type: TABLE; Schema: context; Owner: -
--

CREATE TABLE context.first_party_thread_source_relative_time_anchor (
    anchor_id uuid CONSTRAINT first_party_thread_source_relative_time_anch_anchor_id_not_null NOT NULL,
    thread_source_id uuid CONSTRAINT first_party_thread_source_relative_ti_thread_source_id_not_null NOT NULL,
    link_role text CONSTRAINT first_party_thread_source_relative_time_anch_link_role_not_null NOT NULL,
