--
-- Name: hash_batch; Type: TABLE; Schema: context; Owner: -
--

CREATE TABLE context.hash_batch (
    id uuid DEFAULT uuidv7() NOT NULL,
    activity_execution_id uuid NOT NULL,
    source_version_id uuid NOT NULL,
    attempt integer NOT NULL,
    hash_kind text NOT NULL,
    raw_generation_id uuid,
    normalized_generation_id uuid,
    status text DEFAULT 'open'::text NOT NULL,
    member_count bigint,
    result_ref jsonb,
    activity_receipt_id uuid,
    completed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT hash_batch_attempt_check CHECK ((attempt > 0)),
    CONSTRAINT hash_batch_check1 CHECK ((((status = 'open'::text) AND (member_count IS NULL) AND (result_ref IS NULL) AND (activity_receipt_id IS NULL) AND (completed_at IS NULL)) OR ((status = 'completed'::text) AND (member_count IS NOT NULL) AND (member_count > 0) AND (result_ref IS NOT NULL) AND (activity_receipt_id IS NOT NULL) AND (completed_at IS NOT NULL)) OR ((status = 'aborted'::text) AND (member_count IS NULL) AND (result_ref IS NULL) AND (activity_receipt_id IS NULL) AND (completed_at IS NOT NULL)))),
    CONSTRAINT hash_batch_context_kind_check CHECK ((hash_kind = ANY (ARRAY['context_source_fingerprint'::text, 'context_raw_record_fingerprint'::text, 'context_raw_generation_fingerprint'::text, 'normalized_record_digest'::text, 'normalized_generation_manifest_digest'::text]))),
    CONSTRAINT hash_batch_context_subject_check CHECK ((((hash_kind = 'context_source_fingerprint'::text) AND (raw_generation_id IS NULL) AND (normalized_generation_id IS NULL)) OR ((hash_kind = ANY (ARRAY['context_raw_record_fingerprint'::text, 'context_raw_generation_fingerprint'::text])) AND (raw_generation_id IS NOT NULL) AND (normalized_generation_id IS NULL)) OR ((hash_kind = ANY (ARRAY['normalized_record_digest'::text, 'normalized_generation_manifest_digest'::text])) AND (raw_generation_id IS NULL) AND (normalized_generation_id IS NOT NULL)))),
    CONSTRAINT hash_batch_result_ref_check CHECK (((result_ref IS NULL) OR (jsonb_typeof(result_ref) = 'object'::text))),
    CONSTRAINT hash_batch_status_check CHECK ((status = ANY (ARRAY['open'::text, 'completed'::text, 'aborted'::text])))
);


--
-- Name: hash_batch_member; Type: TABLE; Schema: context; Owner: -
--

CREATE TABLE context.hash_batch_member (
    hash_batch_id uuid NOT NULL,
