    raw_record_id uuid,
    normalized_record_id uuid,
    digest bytea NOT NULL,
    construction text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT hash_batch_member_check CHECK ((num_nonnulls(source_version_id, raw_record_id, normalized_record_id) = 1)),
    CONSTRAINT hash_batch_member_construction_check CHECK ((length(btrim(construction)) > 0)),
    CONSTRAINT hash_batch_member_digest_check CHECK ((octet_length(digest) = 32)),
    CONSTRAINT hash_batch_member_ordinal_check CHECK ((ordinal >= 0))
);


--
-- Name: hash_manifest; Type: TABLE; Schema: context; Owner: -
--

CREATE TABLE context.hash_manifest (
