    CONSTRAINT hash_manifest_check1 CHECK ((((status = 'open'::text) AND (member_count IS NULL) AND (sealed_hash_receipt_id IS NULL) AND (sealed_at IS NULL)) OR ((status = 'sealed'::text) AND (member_count IS NOT NULL) AND (member_count > 0) AND (sealed_hash_receipt_id IS NOT NULL) AND (sealed_at IS NOT NULL)))),
    CONSTRAINT hash_manifest_context_kind_check CHECK ((hash_kind = ANY (ARRAY['context_raw_generation_fingerprint'::text, 'normalized_generation_manifest_digest'::text]))),
    CONSTRAINT hash_manifest_context_subject_check CHECK ((((hash_kind = 'context_raw_generation_fingerprint'::text) AND (raw_generation_id IS NOT NULL) AND (normalized_generation_id IS NULL)) OR ((hash_kind = 'normalized_generation_manifest_digest'::text) AND (raw_generation_id IS NULL) AND (normalized_generation_id IS NOT NULL)))),
    CONSTRAINT hash_manifest_status_check CHECK ((status = ANY (ARRAY['open'::text, 'sealed'::text])))
);


--
-- Name: hash_manifest_member; Type: TABLE; Schema: context; Owner: -
--

