    CONSTRAINT hash_manifest_member_check CHECK (((raw_record_id IS NOT NULL) <> (normalized_record_id IS NOT NULL))),
    CONSTRAINT hash_manifest_member_member_canon_check CHECK ((length(btrim(member_canon)) > 0)),
    CONSTRAINT hash_manifest_member_member_digest_check CHECK ((octet_length(member_digest) = 32)),
    CONSTRAINT hash_manifest_member_ordinal_check CHECK ((ordinal >= 0))
);


--
-- Name: hash_receipt; Type: TABLE; Schema: context; Owner: -
--

CREATE TABLE context.hash_receipt (
    id uuid DEFAULT uuidv7() NOT NULL,
    activity_receipt_id uuid NOT NULL,
    hash_kind text NOT NULL,
    algorithm text DEFAULT 'sha256'::text NOT NULL,
    digest bytea NOT NULL,
    construction text NOT NULL,
    hash_manifest_id uuid,
    source_version_id uuid,
    raw_record_id uuid,
    raw_generation_id uuid,
    normalized_record_id uuid,
    normalized_generation_id uuid,
    computed_at timestamp with time zone NOT NULL,
    computed_by text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT hash_receipt_algorithm_check CHECK ((algorithm = 'sha256'::text)),
    CONSTRAINT hash_receipt_computed_by_check CHECK ((length(btrim(computed_by)) > 0)),
    CONSTRAINT hash_receipt_context_canon_check CHECK ((((hash_kind = 'context_source_fingerprint'::text) AND (construction = 'context-source-fingerprint-v1'::text)) OR ((hash_kind = 'context_raw_record_fingerprint'::text) AND (construction = ANY (ARRAY['context-rawrecord-fingerprint-v1'::text, 'context-rawspan-fingerprint-v1'::text]))) OR ((hash_kind = 'context_raw_generation_fingerprint'::text) AND (construction = 'context-rawgen-fingerprint-chain-v1'::text)) OR ((hash_kind = 'normalized_record_digest'::text) AND (construction = 'normalized-record-postgresql18-jsonb-text-utf8-sha256-v1'::text)) OR ((hash_kind = 'normalized_generation_manifest_digest'::text) AND (construction = 'normalized-generation-ordered-digests-lengthframed-sha256-v1'::text)))),
    CONSTRAINT hash_receipt_context_kind_check CHECK ((hash_kind = ANY (ARRAY['context_source_fingerprint'::text, 'context_raw_record_fingerprint'::text, 'context_raw_generation_fingerprint'::text, 'normalized_record_digest'::text, 'normalized_generation_manifest_digest'::text]))),
    CONSTRAINT hash_receipt_context_subject_check CHECK ((((hash_kind = 'context_source_fingerprint'::text) AND (source_version_id IS NOT NULL) AND (raw_record_id IS NULL) AND (raw_generation_id IS NULL) AND (normalized_record_id IS NULL) AND (normalized_generation_id IS NULL) AND (hash_manifest_id IS NULL)) OR ((hash_kind = 'context_raw_record_fingerprint'::text) AND (source_version_id IS NULL) AND (raw_record_id IS NOT NULL) AND (raw_generation_id IS NULL) AND (normalized_record_id IS NULL) AND (normalized_generation_id IS NULL) AND (hash_manifest_id IS NULL)) OR ((hash_kind = 'context_raw_generation_fingerprint'::text) AND (source_version_id IS NULL) AND (raw_record_id IS NULL) AND (raw_generation_id IS NOT NULL) AND (normalized_record_id IS NULL) AND (normalized_generation_id IS NULL) AND (hash_manifest_id IS NOT NULL)) OR ((hash_kind = 'normalized_record_digest'::text) AND (source_version_id IS NULL) AND (raw_record_id IS NULL) AND (raw_generation_id IS NULL) AND (normalized_record_id IS NOT NULL) AND (normalized_generation_id IS NULL) AND (hash_manifest_id IS NULL)) OR ((hash_kind = 'normalized_generation_manifest_digest'::text) AND (source_version_id IS NULL) AND (raw_record_id IS NULL) AND (raw_generation_id IS NULL) AND (normalized_record_id IS NULL) AND (normalized_generation_id IS NOT NULL) AND (hash_manifest_id IS NOT NULL)))),
    CONSTRAINT hash_receipt_digest_check CHECK ((octet_length(digest) = 32))
);


