    CONSTRAINT proffer_source_context_revision_receipt_ref_check CHECK ((length(btrim(receipt_ref)) > 0)),
    CONSTRAINT proffer_source_context_revision_request_id_check CHECK ((length(btrim(request_id)) > 0)),
    CONSTRAINT proffer_source_context_revision_revision_check CHECK ((revision >= 1)),
    CONSTRAINT proffer_source_context_revision_source_ref_check CHECK ((length(btrim(source_ref)) > 0))
);


--
-- Name: TABLE proffer_source_context_revision; Type: COMMENT; Schema: context; Owner: -
--

COMMENT ON TABLE context.proffer_source_context_revision IS 'Append-only operator assertions kept separate from immutable preview-only source observations. Preview hashes are not custody hashes. Each revision is actor-bound and receipt-addressed.';


