    context_raw_fingerprint_manifest_ref uuid,
    context_raw_generation_fingerprint_ref uuid,
    context_raw_source_verification_ref uuid,
    CONSTRAINT raw_generation_check CHECK ((((status = 'open'::text) AND (sealed_at IS NULL) AND (sealed_by IS NULL)) OR ((status = 'sealed'::text) AND (sealed_at IS NOT NULL) AND (sealed_by IS NOT NULL)))),
    CONSTRAINT raw_generation_format_id_check CHECK ((length(btrim(format_id)) > 0)),
    CONSTRAINT raw_generation_generation_ordinal_check CHECK ((generation_ordinal > 0)),
    CONSTRAINT raw_generation_parser_id_check CHECK ((length(btrim(parser_id)) > 0)),
