);


--
-- Name: raw_record_identity; Type: TABLE; Schema: context; Owner: -
--

CREATE TABLE context.raw_record_identity (
    id uuid DEFAULT uuidv7() NOT NULL,
    raw_generation_id uuid NOT NULL,
    source_version_id uuid NOT NULL,
    format_id text NOT NULL,
    record_ordinal bigint NOT NULL,
    record_status text NOT NULL,
    raw_hash_construction text NOT NULL,
    status_reason text,
    locator_object_id uuid,
    byte_offset bigint,
    byte_length bigint,
    stored_bytes bytea,
    native_metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT raw_record_context_fingerprint_canon_check CHECK ((raw_hash_construction = ANY (ARRAY['context-rawrecord-fingerprint-v1'::text, 'context-rawspan-fingerprint-v1'::text]))),
    CONSTRAINT raw_record_context_span_canon_check CHECK (((record_status <> ALL (ARRAY['envelope'::text, 'unparsed'::text])) OR (raw_hash_construction = 'context-rawspan-fingerprint-v1'::text))),
    CONSTRAINT raw_record_identity_check CHECK (((record_status = 'parsed'::text) OR (status_reason IS NOT NULL))),
    CONSTRAINT raw_record_identity_check2 CHECK ((((stored_bytes IS NOT NULL) AND (locator_object_id IS NULL) AND (byte_offset IS NULL) AND (byte_length IS NULL)) OR ((stored_bytes IS NULL) AND (locator_object_id IS NOT NULL) AND (byte_offset IS NOT NULL) AND (byte_offset >= 0) AND (byte_length IS NOT NULL) AND (byte_length >= 0)))),
    CONSTRAINT raw_record_identity_native_metadata_check CHECK ((jsonb_typeof(native_metadata) = 'object'::text)),
    CONSTRAINT raw_record_identity_record_ordinal_check CHECK ((record_ordinal >= 0)),
    CONSTRAINT raw_record_identity_record_status_check CHECK ((record_status = ANY (ARRAY['parsed'::text, 'rejected'::text, 'malformed'::text, 'unknown'::text, 'unparsed'::text, 'envelope'::text])))
);


