--
-- Name: reconciliation_receipt; Type: TABLE; Schema: context; Owner: -
--

CREATE TABLE context.reconciliation_receipt (
    id uuid DEFAULT uuidv7() NOT NULL,
    activity_receipt_id uuid NOT NULL,
    reconciliation_kind text NOT NULL,
    raw_generation_id uuid,
    normalized_generation_id uuid,
    status text NOT NULL,
    expected jsonb DEFAULT '{}'::jsonb NOT NULL,
    observed jsonb DEFAULT '{}'::jsonb NOT NULL,
    discrepancies jsonb DEFAULT '[]'::jsonb NOT NULL,
    verified_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT reconciliation_context_raw_source_check CHECK (((reconciliation_kind <> 'raw_source_verification'::text) OR ((expected ? 'context_raw_generation_fingerprint'::text) AND (expected ? 'context_source_fingerprint'::text) AND (observed ? 'context_raw_generation_fingerprint'::text) AND (observed ? 'context_source_fingerprint'::text) AND ((expected ->> 'verification_mode'::text) = 'retained_bytes_recomputation'::text) AND ((observed ->> 'verification_mode'::text) = 'retained_bytes_recomputation'::text) AND ((status <> 'success'::text) OR ((expected -> 'context_raw_generation_fingerprint'::text) = (observed -> 'context_raw_generation_fingerprint'::text))) AND ((status <> 'success'::text) OR ((expected -> 'context_source_fingerprint'::text) = (observed -> 'context_source_fingerprint'::text)))))),
    CONSTRAINT reconciliation_receipt_check CHECK ((((reconciliation_kind = ANY (ARRAY['record_accounting'::text, 'byte_coverage'::text, 'raw_source_verification'::text])) AND (raw_generation_id IS NOT NULL) AND (normalized_generation_id IS NULL)) OR ((reconciliation_kind = ANY (ARRAY['raw_lineage_validation'::text, 'normalized_generation_verification'::text])) AND (raw_generation_id IS NULL) AND (normalized_generation_id IS NOT NULL)))),
    CONSTRAINT reconciliation_receipt_check1 CHECK ((((status = 'success'::text) AND (discrepancies = '[]'::jsonb)) OR (status = ANY (ARRAY['failed'::text, 'not_applicable'::text])))),
    CONSTRAINT reconciliation_receipt_check2 CHECK (((status <> 'not_applicable'::text) OR (discrepancies = '[]'::jsonb))),
    CONSTRAINT reconciliation_receipt_check4 CHECK (((reconciliation_kind <> 'normalized_generation_verification'::text) OR ((expected ? 'normalized_generation_manifest_digest'::text) AND (observed ? 'normalized_generation_manifest_digest'::text) AND ((expected ->> 'verification_mode'::text) = 'independent_recomputation'::text) AND ((observed ->> 'verification_mode'::text) = 'independent_recomputation'::text) AND ((status <> 'success'::text) OR ((expected -> 'normalized_generation_manifest_digest'::text) = (observed -> 'normalized_generation_manifest_digest'::text)))))),
    CONSTRAINT reconciliation_receipt_discrepancies_check CHECK ((jsonb_typeof(discrepancies) = 'array'::text)),
    CONSTRAINT reconciliation_receipt_expected_check CHECK ((jsonb_typeof(expected) = 'object'::text)),
    CONSTRAINT reconciliation_receipt_observed_check CHECK ((jsonb_typeof(observed) = 'object'::text)),
    CONSTRAINT reconciliation_receipt_reconciliation_kind_check CHECK ((reconciliation_kind = ANY (ARRAY['record_accounting'::text, 'byte_coverage'::text, 'raw_source_verification'::text, 'raw_lineage_validation'::text, 'normalized_generation_verification'::text]))),
    CONSTRAINT reconciliation_receipt_status_check CHECK ((status = ANY (ARRAY['success'::text, 'failed'::text, 'not_applicable'::text])))
);


--
-- Name: relative_time_anchor; Type: TABLE; Schema: context; Owner: -
--

CREATE TABLE context.relative_time_anchor (
    id uuid DEFAULT uuidv7() NOT NULL,
    anchor_key uuid DEFAULT uuidv7() NOT NULL,
    version_ordinal integer NOT NULL,
    placement_kind text NOT NULL,
    lower_bound_at timestamp with time zone,
    upper_bound_at timestamp with time zone,
    last_known_before_anchor_id uuid,
    first_known_after_anchor_id uuid,
    contextual_sequence_key text,
    contextual_sequence_ordinal bigint,
    metadata_basis text NOT NULL,
    raw_metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    raw_metadata_ref text,
    confidence double precision NOT NULL,
    ambiguity text,
    review_state text NOT NULL,
    reviewed_by text,
    reviewed_at timestamp with time zone,
    provenance_digest bytea NOT NULL,
    supersedes_id uuid,
    presentation_payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT relative_time_anchor_check CHECK (((upper_bound_at IS NULL) OR (lower_bound_at IS NULL) OR (upper_bound_at >= lower_bound_at))),
    CONSTRAINT relative_time_anchor_check1 CHECK (((contextual_sequence_ordinal IS NULL) OR (contextual_sequence_key IS NOT NULL))),
    CONSTRAINT relative_time_anchor_check2 CHECK (((lower_bound_at IS NOT NULL) OR (upper_bound_at IS NOT NULL) OR (last_known_before_anchor_id IS NOT NULL) OR (first_known_after_anchor_id IS NOT NULL) OR (contextual_sequence_key IS NOT NULL))),
    CONSTRAINT relative_time_anchor_check3 CHECK (((last_known_before_anchor_id IS DISTINCT FROM id) AND (first_known_after_anchor_id IS DISTINCT FROM id))),
    CONSTRAINT relative_time_anchor_check4 CHECK (((review_state <> 'approved'::text) OR ((reviewed_by IS NOT NULL) AND (reviewed_at IS NOT NULL)))),
    CONSTRAINT relative_time_anchor_confidence_check CHECK (((confidence >= (0)::double precision) AND (confidence <= (1)::double precision))),
    CONSTRAINT relative_time_anchor_metadata_basis_check CHECK ((length(btrim(metadata_basis)) > 0)),
    CONSTRAINT relative_time_anchor_placement_kind_check CHECK ((placement_kind = ANY (ARRAY['before'::text, 'after'::text, 'between'::text, 'sequence_only'::text, 'metadata_approximation'::text]))),
    CONSTRAINT relative_time_anchor_presentation_payload_check CHECK ((jsonb_typeof(presentation_payload) = 'object'::text)),
    CONSTRAINT relative_time_anchor_provenance_digest_check CHECK ((octet_length(provenance_digest) = 32)),
    CONSTRAINT relative_time_anchor_raw_metadata_check CHECK ((jsonb_typeof(raw_metadata) = 'object'::text)),
    CONSTRAINT relative_time_anchor_review_state_check CHECK ((review_state = ANY (ARRAY['proposed'::text, 'approved'::text, 'rejected'::text, 'superseded'::text]))),
    CONSTRAINT relative_time_anchor_version_ordinal_check CHECK ((version_ordinal > 0))
);


