    CONSTRAINT repair_resolution_check CHECK (((applied AND (tool_id = ANY (ARRAY['repair.write-derived'::text, 'repair.pdf-derived'::text])) AND (active_object_id <> original_object_id)) OR ((NOT applied) AND (tool_id IS NULL) AND (tool_result = '{}'::jsonb) AND (active_object_id = original_object_id)))),
    CONSTRAINT repair_resolution_tool_result_check CHECK (((jsonb_typeof(tool_result) = 'object'::text) AND (octet_length((tool_result)::text) <= 2097152)))
);


