    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    verification_state text DEFAULT 'proposed'::text NOT NULL,
    CONSTRAINT court_case_caption_check CHECK ((length(btrim(caption)) > 0)),
    CONSTRAINT court_case_created_by_check CHECK ((length(btrim(created_by)) > 0)),
    CONSTRAINT court_case_dates_ck CHECK (((closed_on IS NULL) OR (filed_on IS NULL) OR (closed_on >= filed_on))),
    CONSTRAINT court_case_status_check CHECK ((status = ANY (ARRAY['pre_filing'::text, 'active'::text, 'stayed'::text, 'closed'::text, 'appealed'::text, 'archived'::text]))),
    CONSTRAINT court_case_verification_state_check CHECK ((verification_state = ANY (ARRAY['proposed'::text, 'confirmed'::text, 'disputed'::text])))
);


