);


--
-- Name: event_candidate; Type: TABLE; Schema: timeline; Owner: -
--

CREATE TABLE timeline.event_candidate (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    source_system text NOT NULL,
    source_record_id text NOT NULL,
    source_record_version text,
    source_locator jsonb DEFAULT '{}'::jsonb NOT NULL,
    extraction_run_id text,
    temporal_precision text NOT NULL,
    occurred_at timestamp with time zone,
    valid_from timestamp with time zone,
    valid_to timestamp with time zone,
    temporal_confidence real,
    display_summary text NOT NULL,
    event_type text NOT NULL,
    entity_refs text[] DEFAULT '{}'::text[] NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT event_candidate_temporal_confidence_check CHECK (((temporal_confidence IS NULL) OR ((temporal_confidence >= (0)::double precision) AND (temporal_confidence <= (1)::double precision)))),
    CONSTRAINT event_candidate_temporal_precision_check CHECK ((temporal_precision = ANY (ARRAY['point'::text, 'interval'::text, 'uncertain'::text])))
);


--
-- Name: TABLE event_candidate; Type: COMMENT; Schema: timeline; Owner: -
--

COMMENT ON TABLE timeline.event_candidate IS 'Any-context event proposal (ADR-0060). CANDIDATE authority only -- D-082: an AI-chat-derived row is a lead, never evidence. A correction is a NEW row (new extraction_run_id), never an edit to this one -- see the append-only trigger below.';


--
-- Name: COLUMN event_candidate.source_locator; Type: COMMENT; Schema: timeline; Owner: -
--

COMMENT ON COLUMN timeline.event_candidate.source_locator IS 'Compatibility/presentation projection only. Typed source authority is timeline.event_candidate_source_range -> context.source_range_locator.';


--
-- Name: event_candidate_relative_time_anchor; Type: TABLE; Schema: timeline; Owner: -
--

CREATE TABLE timeline.event_candidate_relative_time_anchor (
    event_candidate_id uuid CONSTRAINT event_candidate_relative_time_ancho_event_candidate_id_not_null NOT NULL,
    anchor_id uuid NOT NULL,
    anchor_role text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT event_candidate_relative_time_anchor_anchor_role_check CHECK ((anchor_role = ANY (ARRAY['occurred_at'::text, 'valid_from'::text, 'valid_to'::text, 'source_available_from'::text, 'realizable_from'::text])))
);


--
-- Name: TABLE event_candidate_relative_time_anchor; Type: COMMENT; Schema: timeline; Owner: -
--

COMMENT ON TABLE timeline.event_candidate_relative_time_anchor IS 'Typed append-only relative-time link for event-candidate temporal roles. Corrections are new anchor versions/links, never JSON authority.';


--
-- Name: event_candidate_source_range; Type: TABLE; Schema: timeline; Owner: -
--

CREATE TABLE timeline.event_candidate_source_range (
    id uuid DEFAULT uuidv7() NOT NULL,
    event_candidate_id uuid NOT NULL,
    source_version_id uuid NOT NULL,
    source_range_locator_id uuid NOT NULL,
    member_ordinal bigint NOT NULL,
    extractor_id text NOT NULL,
    extractor_version text NOT NULL,
    schema_manifest_digest bytea NOT NULL,
    extraction_activity_receipt_id uuid CONSTRAINT event_candidate_source_rang_extraction_activity_receip_not_null NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT event_candidate_source_range_extractor_id_check CHECK ((length(btrim(extractor_id)) > 0)),
    CONSTRAINT event_candidate_source_range_extractor_version_check CHECK ((length(btrim(extractor_version)) > 0)),
    CONSTRAINT event_candidate_source_range_member_ordinal_check CHECK ((member_ordinal >= 0)),
    CONSTRAINT event_candidate_source_range_schema_manifest_digest_check CHECK ((octet_length(schema_manifest_digest) = 32))
);


--
-- Name: TABLE event_candidate_source_range; Type: COMMENT; Schema: timeline; Owner: -
--

COMMENT ON TABLE timeline.event_candidate_source_range IS 'Independent event-extraction provenance over the same immutable source_version/range primitive; it never carves content out of or depends on chunks.';


--
-- Name: timeline_collection; Type: TABLE; Schema: timeline; Owner: -
--

CREATE TABLE timeline.timeline_collection (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    slug text NOT NULL,
    title text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE timeline_collection; Type: COMMENT; Schema: timeline; Owner: -
--

COMMENT ON TABLE timeline.timeline_collection IS 'D-072 single-case timeline collection(s). Curated membership set -- authority stays with the member row it points at, never copied here.';


--
-- Name: timeline_member; Type: TABLE; Schema: timeline; Owner: -
--

CREATE TABLE timeline.timeline_member (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    collection_id uuid NOT NULL,
    member_authority text NOT NULL,
    candidate_id uuid,
    governed_source_schema text,
    governed_source_table text,
    governed_source_pk text,
    governed_source_version text,
    display_order numeric,
    group_label text,
    included boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT timeline_member_authority_shape_ck CHECK ((((member_authority = 'candidate_context'::text) AND (candidate_id IS NOT NULL) AND (governed_source_schema IS NULL) AND (governed_source_table IS NULL) AND (governed_source_pk IS NULL)) OR ((member_authority = 'evidence_approved'::text) AND (candidate_id IS NULL) AND (governed_source_schema IS NOT NULL) AND (governed_source_table IS NOT NULL) AND (governed_source_pk IS NOT NULL)))),
    CONSTRAINT timeline_member_member_authority_check CHECK ((member_authority = ANY (ARRAY['candidate_context'::text, 'evidence_approved'::text])))
);


--
-- Name: TABLE timeline_member; Type: COMMENT; Schema: timeline; Owner: -
--

COMMENT ON TABLE timeline.timeline_member IS 'Curated timeline membership (ADR-0060). Retains candidate vs evidence-approved authority via member_authority; never copies the source row''s own content. An edit to an evidence_approved member is out of this table''s scope -- it becomes a WP-F02 amendment candidate elsewhere, never an UPDATE here.';


--
-- Name: timeline_projection_activation; Type: TABLE; Schema: timeline; Owner: -
--

CREATE TABLE timeline.timeline_projection_activation (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    generation_id uuid NOT NULL,
    activated_by text NOT NULL,
    note text,
    activated_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE timeline_projection_activation; Type: COMMENT; Schema: timeline; Owner: -
--

COMMENT ON TABLE timeline.timeline_projection_activation IS 'Append-only activation attestation log (R09 Phase 7). Current active generation = the row with the latest activated_at; never mutate a prior row to "deactivate" it.';


--
-- Name: timeline_projection_generation; Type: TABLE; Schema: timeline; Owner: -
--

CREATE TABLE timeline.timeline_projection_generation (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    sequence bigint NOT NULL,
    collection_id uuid NOT NULL,
    status text DEFAULT 'sealed'::text NOT NULL,
    policy_version text DEFAULT 'adr-0060-timesketch-mapping-v1'::text NOT NULL,
    member_count integer NOT NULL,
    membership_hash text NOT NULL,
    content_hash text NOT NULL,
    idempotency_key text NOT NULL,
    since_generation_id uuid,
    superseded_by uuid,
    created_by text DEFAULT 'timeline_projector'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT timeline_projection_generation_status_check CHECK ((status = ANY (ARRAY['sealed'::text, 'superseded'::text, 'quarantined'::text])))
);


--
-- Name: TABLE timeline_projection_generation; Type: COMMENT; Schema: timeline; Owner: -
--

COMMENT ON TABLE timeline.timeline_projection_generation IS 'Immutable, sealed Timesketch export generation (ADR-0060/D-085). sequence is the monotonically comparable outbox-style cursor R09 walks; idempotency_key makes rebuilding from an unchanged member set a no-op instead of a duplicate.';


--
-- Name: timeline_projection_generation_sequence_seq; Type: SEQUENCE; Schema: timeline; Owner: -
--

ALTER TABLE timeline.timeline_projection_generation ALTER COLUMN sequence ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME timeline.timeline_projection_generation_sequence_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: timeline_projection_member; Type: TABLE; Schema: timeline; Owner: -
--

CREATE TABLE timeline.timeline_projection_member (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    generation_id uuid NOT NULL,
    source_member_id uuid NOT NULL,
    stable_member_id text NOT NULL,
    opensearch_doc_id text NOT NULL,
    authority_state text NOT NULL,
    amends_stable_member_id text,
    display_at_utc timestamp with time zone NOT NULL,
    display_summary text NOT NULL,
    event_type text NOT NULL,
    temporal_precision text NOT NULL,
    occurred_at timestamp with time zone,
    valid_from timestamp with time zone,
    valid_to timestamp with time zone,
    temporal_confidence real,
    source_available_from timestamp with time zone NOT NULL,
    entity_refs text[] DEFAULT '{}'::text[] NOT NULL,
    verification_state text DEFAULT 'unverified'::text NOT NULL,
    privacy_level text,
    privileged boolean DEFAULT false NOT NULL,
    source_system text NOT NULL,
    source_record_id text NOT NULL,
    source_record_version text,
    core_content_hash text NOT NULL,
    annotation_content_hash text NOT NULL,
    change_class text DEFAULT 'core'::text NOT NULL,
    member_content_hash text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT timeline_projection_member_amendment_shape_ck CHECK ((((authority_state = 'amendment_candidate'::text) AND (amends_stable_member_id IS NOT NULL)) OR ((authority_state <> 'amendment_candidate'::text) AND (amends_stable_member_id IS NULL)))),
    CONSTRAINT timeline_projection_member_authority_state_check CHECK ((authority_state = ANY (ARRAY['candidate_context'::text, 'evidence_approved'::text, 'amendment_candidate'::text]))),
    CONSTRAINT timeline_projection_member_change_class_check CHECK ((change_class = ANY (ARRAY['core'::text, 'annotation'::text, 'unchanged'::text]))),
    CONSTRAINT timeline_projection_member_temporal_confidence_check CHECK (((temporal_confidence IS NULL) OR ((temporal_confidence >= (0)::double precision) AND (temporal_confidence <= (1)::double precision)))),
    CONSTRAINT timeline_projection_member_temporal_precision_check CHECK ((temporal_precision = ANY (ARRAY['point'::text, 'interval'::text, 'uncertain'::text]))),
    CONSTRAINT timeline_projection_member_verification_state_check CHECK ((verification_state = ANY (ARRAY['unverified'::text, 'disputed'::text, 'verified'::text, 'revoked'::text, 'superseded'::text])))
);


--
-- Name: TABLE timeline_projection_member; Type: COMMENT; Schema: timeline; Owner: -
--

COMMENT ON TABLE timeline.timeline_projection_member IS 'One immutable row per member per sealed generation (ADR-0060 canonical mapping). stable_member_id/opensearch_doc_id are deterministic functions of source_member_id, never of the generation, so rebuild/replay always targets the same logical OpenSearch document.';


--
-- Name: COLUMN timeline_projection_member.change_class; Type: COMMENT; Schema: timeline; Owner: -
--

COMMENT ON COLUMN timeline.timeline_projection_member.change_class IS 'Relative to this stable_member_id''s row in the immediately-prior generation (if any): "core" = core_content_hash differs, "annotation" = only annotation_content_hash differs, "unchanged" = neither differs (member_content_hash identical) -- R09 uses this to decide reindex vs annotation-refresh vs skip.';


--
-- Name: timeline_projection_receipt; Type: TABLE; Schema: timeline; Owner: -
--

CREATE TABLE timeline.timeline_projection_receipt (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    generation_id uuid NOT NULL,
    member_id uuid,
    sink text DEFAULT 'timesketch_opensearch'::text NOT NULL,
    idempotency_key text NOT NULL,
    status text NOT NULL,
    attempt integer DEFAULT 1 NOT NULL,
    expected_content_hash text,
    observed_content_hash text,
    opensearch_doc_id text,
    opensearch_index text,
    error_code text,
    error_digest text,
    started_at timestamp with time zone,
    finished_at timestamp with time zone,
    observed_at timestamp with time zone,
    previous_receipt_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT timeline_projection_receipt_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'attempted'::text, 'succeeded'::text, 'failed_retryable'::text, 'failed_terminal'::text, 'quarantined'::text, 'superseded'::text])))
);


--
-- Name: TABLE timeline_projection_receipt; Type: COMMENT; Schema: timeline; Owner: -
--

COMMENT ON TABLE timeline.timeline_projection_receipt IS 'Append-only delivery/read-back receipt (R09 common-receipt shape). A current-status view is derived below -- rows here are never updated, a new attempt/observation is a new row.';


--
-- Name: vw_projection_expected_manifest; Type: VIEW; Schema: timeline; Owner: -
--

CREATE VIEW timeline.vw_projection_expected_manifest AS
 SELECT g.id AS generation_id,
    g.sequence,
    g.status,
    g.membership_hash,
    g.content_hash,
    m.stable_member_id,
    m.opensearch_doc_id,
    m.member_content_hash,
    m.authority_state,
    m.change_class
   FROM (timeline.timeline_projection_generation g
     JOIN timeline.timeline_projection_member m ON ((m.generation_id = g.id)))
  ORDER BY g.sequence, m.stable_member_id;


--
-- Name: VIEW vw_projection_expected_manifest; Type: COMMENT; Schema: timeline; Owner: -
--

COMMENT ON VIEW timeline.vw_projection_expected_manifest IS 'R09/WP-H01 expected-manifest read: ordered (generation, member) rows with the hashes a reconciliation run diffs against OpenSearch read-back observations.';


--
-- Name: vw_projection_receipt_current; Type: VIEW; Schema: timeline; Owner: -
--

CREATE VIEW timeline.vw_projection_receipt_current AS
 SELECT DISTINCT ON (generation_id, member_id, sink) generation_id,
    member_id,
    sink,
    status,
    attempt,
    expected_content_hash,
    observed_content_hash,
    opensearch_doc_id,
    opensearch_index,
    error_code,
    error_digest,
    started_at,
    finished_at,
    observed_at,
    id AS receipt_id,
    created_at
   FROM timeline.timeline_projection_receipt
  ORDER BY generation_id, member_id, sink, created_at DESC, id DESC;


--
-- Name: VIEW vw_projection_receipt_current; Type: COMMENT; Schema: timeline; Owner: -
--

COMMENT ON VIEW timeline.vw_projection_receipt_current IS 'Latest receipt per (generation, member, sink) -- the derived current-status read, not a source of truth (the append-only receipt rows are).';


