    source_event_table text NOT NULL,
    source_event_id bigint NOT NULL,
    row_data jsonb NOT NULL,
    error_class text NOT NULL,
    error_message text NOT NULL,
    attempts integer NOT NULL,
    failed_at timestamp with time zone DEFAULT now() NOT NULL,
    replay_requested_at timestamp with time zone,
    resolved_at timestamp with time zone,
    resolution_note text,
    CONSTRAINT cdc_dead_letter_attempts_check CHECK ((attempts > 0)),
    CONSTRAINT cdc_dead_letter_check CHECK (((resolved_at IS NULL) OR (resolved_at >= failed_at))),
    CONSTRAINT cdc_dead_letter_source_event_id_check CHECK ((source_event_id > 0))
);


--
-- Name: TABLE cdc_dead_letter; Type: COMMENT; Schema: working; Owner: -
--

COMMENT ON TABLE working.cdc_dead_letter IS 'Poison-pill quarantine (D-054 ruling 7). The cursor advances PAST a dead-lettered event so one bad row never stalls the lane; the replay tool drains this table after a fix. Alert on count(*) WHERE resolved_at IS NULL > 0 is mandatory.';


--
-- Name: cdc_sink; Type: TABLE; Schema: working; Owner: -
--

CREATE TABLE working.cdc_sink (
