    promotion_only boolean DEFAULT false NOT NULL,
    registered_at timestamp with time zone DEFAULT now() NOT NULL,
    notes text,
    CONSTRAINT cdc_sink_drain_xor_promotion CHECK ((NOT (auto_drain AND promotion_only))),
    CONSTRAINT cdc_sink_surreal_is_promotion_only CHECK (((sink_id <> 'surrealdb'::text) OR ((auto_drain = false) AND (promotion_only = true))))
);


--
-- Name: TABLE cdc_sink; Type: COMMENT; Schema: working; Owner: -
--

COMMENT ON TABLE working.cdc_sink IS 'Subscribers of the ADR-0052 spine. auto_drain sinks are drained by the Part-2 worker; promotion_only sinks (surrealdb, D-107) may only have promotion CANDIDATES raised for an explicit owner decision -- Temporal executes and receipts that decision and MUST NOT infer it.';


