    attrs jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    graph_lane analysis.graph_lane,
    prompt_version text,
    source_generation bigint,
    projected_at timestamp with time zone,
    CONSTRAINT claim_candidate_assistant_is_proposal CHECK (((speaker_role = 'assistant'::text) = (claim_class = 'AI_PROPOSAL'::text))),
    CONSTRAINT claim_candidate_attrs_check CHECK ((jsonb_typeof(attrs) = 'object'::text)),
    CONSTRAINT claim_candidate_body_check CHECK ((length(btrim(body)) > 0)),
    CONSTRAINT claim_candidate_check CHECK (((span_end IS NULL) OR (span_end >= span_start))),
    CONSTRAINT claim_candidate_claim_class_check CHECK ((claim_class = ANY (ARRAY['SELF_ACCOUNT'::text, 'SELF_ALLEGATION'::text, 'REPORTED_SPEECH'::text, 'DOCUMENT_QUOTE'::text, 'AI_PROPOSAL'::text, 'UNKNOWN'::text]))),
    CONSTRAINT claim_candidate_confidence_check CHECK (((confidence IS NULL) OR ((confidence >= (0)::double precision) AND (confidence <= (1)::double precision)))),
    CONSTRAINT claim_candidate_content_sha256_check CHECK ((octet_length(content_sha256) = 32)),
    CONSTRAINT claim_candidate_extractor_check CHECK ((length(btrim(extractor)) > 0)),
    CONSTRAINT claim_candidate_extractor_version_check CHECK ((length(btrim(extractor_version)) > 0)),
    CONSTRAINT claim_candidate_fingerprint_check CHECK ((length(btrim(fingerprint)) > 0)),
    CONSTRAINT claim_candidate_hedge_consistency CHECK ((hedged OR (cardinality(hedge_terms) = 0))),
    CONSTRAINT claim_candidate_message_ordinal_check CHECK ((message_ordinal >= 0)),
    CONSTRAINT claim_candidate_review_is_attributed CHECK (((review_state = 'pending'::text) OR ((reviewed_by IS NOT NULL) AND (reviewed_at IS NOT NULL)))),
    CONSTRAINT claim_candidate_review_state_check CHECK ((review_state = ANY (ARRAY['pending'::text, 'approved'::text, 'rejected'::text, 'needs_info'::text, 'superseded'::text]))),
    CONSTRAINT claim_candidate_span_start_check CHECK (((span_start IS NULL) OR (span_start >= 0))),
    CONSTRAINT claim_candidate_speaker_role_check CHECK ((speaker_role = ANY (ARRAY['human'::text, 'assistant'::text, 'system'::text, 'unknown'::text]))),
    CONSTRAINT claim_candidate_title_check CHECK ((length(btrim(title)) > 0)),
    CONSTRAINT claim_candidate_verbatim_check CHECK (((length(verbatim) >= 1) AND (length(verbatim) <= 300)))
);


