    CONSTRAINT claim_temporal_edge_attrs_check CHECK ((jsonb_typeof(attrs) = 'object'::text)),
    CONSTRAINT claim_temporal_edge_confidence_check CHECK (((confidence IS NULL) OR ((confidence >= (0)::double precision) AND (confidence <= (1)::double precision)))),
    CONSTRAINT claim_temporal_edge_no_self_reference CHECK (((from_claim_id IS DISTINCT FROM to_claim_id) AND (from_claim_id IS DISTINCT FROM resolved_claim_id))),
    CONSTRAINT claim_temporal_edge_relation_check CHECK ((relation = ANY (ARRAY['before'::text, 'after'::text, 'same_window'::text, 'during'::text, 'approximately_at'::text]))),
    CONSTRAINT claim_temporal_edge_resolution_is_complete CHECK ((((resolved_claim_id IS NULL) AND (resolved_by IS NULL) AND (resolved_at IS NULL)) OR ((resolved_claim_id IS NOT NULL) AND (resolved_by IS NOT NULL) AND (resolved_at IS NOT NULL) AND (target_kind = 'unresolved_phrase'::text)))),
    CONSTRAINT claim_temporal_edge_review_state_check CHECK ((review_state = ANY (ARRAY['pending'::text, 'approved'::text, 'rejected'::text, 'needs_info'::text, 'superseded'::text]))),
    CONSTRAINT claim_temporal_edge_target_is_complete CHECK ((((target_kind = 'claim'::text) AND (to_claim_id IS NOT NULL) AND (target_phrase IS NULL)) OR ((target_kind = 'unresolved_phrase'::text) AND (to_claim_id IS NULL) AND (target_phrase IS NOT NULL) AND (length(btrim(target_phrase)) > 0)))),
    CONSTRAINT claim_temporal_edge_target_kind_check CHECK ((target_kind = ANY (ARRAY['claim'::text, 'unresolved_phrase'::text])))
);


--
-- Name: content_chunk; Type: TABLE; Schema: working; Owner: -
