    CONSTRAINT content_chunk_check CHECK ((public.digest(convert_to(content, 'UTF8'::name), 'sha256'::text) = content_sha256)),
    CONSTRAINT content_chunk_chunk_index_check CHECK ((chunk_index >= 0)),
