    CONSTRAINT content_chunk_content_sha256_check CHECK ((octet_length(content_sha256) = 32)),
    CONSTRAINT content_chunk_derivation_mode_check CHECK ((derivation_mode = ANY (ARRAY['verbatim_span'::text, 'composed'::text, 'unverified_derived'::text]))),
    CONSTRAINT content_chunk_token_count_check CHECK (((token_count IS NULL) OR (token_count >= 0)))
);


--
-- Name: TABLE content_chunk; Type: COMMENT; Schema: working; Owner: -
--

COMMENT ON TABLE working.content_chunk IS 'THE chunk model (D-116). chat_chunk and normalized_record_chunk are deleted. Hash column convention: content_sha256; "content_hash" is banned.';


--
-- Name: COLUMN content_chunk.derivation_mode; Type: COMMENT; Schema: working; Owner: -
--

COMMENT ON COLUMN working.content_chunk.derivation_mode IS 'Semantica StructuralChunker negative fixture f2e9d2a: its rebuilt text omitted 176 chars and 24/35 chunks were non-verbatim. Such text cannot seal a complete verbatim generation; exact original-byte offsets remain the authority.';


--
-- Name: content_chunk_current_classification; Type: VIEW; Schema: working; Owner: -
--

CREATE VIEW working.content_chunk_current_classification AS
 SELECT DISTINCT ON (chunk_id) chunk_id,
    id AS decision_id,
    decision_version,
    lane,
    review_state,
    classifier_id,
    classifier_version,
    confidence,
    reviewed_by,
    reviewed_at
   FROM analysis.content_chunk_classification_decision
  WHERE (review_state = ANY (ARRAY['system_initial'::text, 'human_approved'::text]))
  ORDER BY chunk_id, decision_version DESC, created_at DESC, id DESC;


