--
-- Name: content_chunk_generation; Type: TABLE; Schema: working; Owner: -
--

CREATE TABLE working.content_chunk_generation (
    id uuid DEFAULT uuidv7() NOT NULL,
    source_version_id uuid NOT NULL,
    normalized_generation_id uuid,
    generation_ordinal integer NOT NULL,
    status text DEFAULT 'open'::text NOT NULL,
    completeness_scope text DEFAULT 'complete'::text NOT NULL,
    requires_verbatim_reassembly boolean DEFAULT true NOT NULL,
    policy_id text NOT NULL,
    policy_version text NOT NULL,
    chunker_id text NOT NULL,
    chunker_version text NOT NULL,
    config_digest bytea NOT NULL,
    schema_version text NOT NULL,
    implementation_digest bytea NOT NULL,
    source_view text NOT NULL,
    source_canonicalization text NOT NULL,
    source_sha256 bytea NOT NULL,
    source_byte_length bigint NOT NULL,
    source_codepoint_length bigint,
    chunk_count bigint,
    member_count bigint,
    manifest_sha256 bytea,
    activity_execution_id uuid NOT NULL,
    activity_receipt_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    sealed_at timestamp with time zone,
    sealed_by text,
    aborted_at timestamp with time zone,
    abort_reason text,
    CONSTRAINT content_chunk_generation_check CHECK ((((status = 'open'::text) AND (sealed_at IS NULL) AND (sealed_by IS NULL) AND (aborted_at IS NULL) AND (abort_reason IS NULL) AND (chunk_count IS NULL) AND (member_count IS NULL) AND (manifest_sha256 IS NULL)) OR ((status = 'sealed'::text) AND (sealed_at IS NOT NULL) AND (length(btrim(sealed_by)) > 0) AND (aborted_at IS NULL) AND (abort_reason IS NULL) AND (chunk_count IS NOT NULL) AND (member_count IS NOT NULL) AND (manifest_sha256 IS NOT NULL)) OR ((status = 'aborted'::text) AND (sealed_at IS NULL) AND (sealed_by IS NULL) AND (aborted_at IS NOT NULL) AND (length(btrim(abort_reason)) > 0)))),
    CONSTRAINT content_chunk_generation_chunk_count_check CHECK (((chunk_count IS NULL) OR (chunk_count >= 0))),
    CONSTRAINT content_chunk_generation_chunker_id_check CHECK ((length(btrim(chunker_id)) > 0)),
    CONSTRAINT content_chunk_generation_chunker_version_check CHECK ((length(btrim(chunker_version)) > 0)),
    CONSTRAINT content_chunk_generation_completeness_scope_check CHECK ((completeness_scope = 'complete'::text)),
    CONSTRAINT content_chunk_generation_config_digest_check CHECK ((octet_length(config_digest) = 32)),
    CONSTRAINT content_chunk_generation_generation_ordinal_check CHECK ((generation_ordinal > 0)),
    CONSTRAINT content_chunk_generation_implementation_digest_check CHECK ((octet_length(implementation_digest) = 32)),
    CONSTRAINT content_chunk_generation_manifest_sha256_check CHECK (((manifest_sha256 IS NULL) OR (octet_length(manifest_sha256) = 32))),
    CONSTRAINT content_chunk_generation_member_count_check CHECK (((member_count IS NULL) OR (member_count >= 0))),
    CONSTRAINT content_chunk_generation_policy_id_check CHECK ((length(btrim(policy_id)) > 0)),
    CONSTRAINT content_chunk_generation_policy_version_check CHECK ((length(btrim(policy_version)) > 0)),
    CONSTRAINT content_chunk_generation_schema_version_check CHECK ((length(btrim(schema_version)) > 0)),
    CONSTRAINT content_chunk_generation_source_byte_length_check CHECK ((source_byte_length >= 0)),
    CONSTRAINT content_chunk_generation_source_canonicalization_check CHECK ((length(btrim(source_canonicalization)) > 0)),
    CONSTRAINT content_chunk_generation_source_codepoint_length_check CHECK (((source_codepoint_length IS NULL) OR (source_codepoint_length >= 0))),
    CONSTRAINT content_chunk_generation_source_sha256_check CHECK ((octet_length(source_sha256) = 32)),
    CONSTRAINT content_chunk_generation_source_view_check CHECK ((length(btrim(source_view)) > 0)),
    CONSTRAINT content_chunk_generation_status_check CHECK ((status = ANY (ARRAY['open'::text, 'sealed'::text, 'aborted'::text])))
);


