--
-- Name: content_chunk_reassembly_receipt; Type: TABLE; Schema: working; Owner: -
--

CREATE TABLE working.content_chunk_reassembly_receipt (
    id uuid DEFAULT uuidv7() NOT NULL,
    generation_id uuid NOT NULL,
    source_version_id uuid NOT NULL,
    source_sha256 bytea NOT NULL,
    reassembled_sha256 bytea NOT NULL,
    source_byte_length bigint NOT NULL,
    reassembled_byte_length bigint CONSTRAINT content_chunk_reassembly_recei_reassembled_byte_length_not_null NOT NULL,
    covered_range_start bigint DEFAULT 0 NOT NULL,
    covered_range_end bigint NOT NULL,
    gap_count bigint NOT NULL,
    overlap_count bigint NOT NULL,
    chunk_count bigint NOT NULL,
    member_count bigint NOT NULL,
    verification_result text NOT NULL,
    verifier_id text NOT NULL,
    verifier_version text NOT NULL,
    activity_receipt_id uuid NOT NULL,
    verified_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT content_chunk_reassembly_receipt_check CHECK ((covered_range_end >= covered_range_start)),
    CONSTRAINT content_chunk_reassembly_receipt_check1 CHECK (((verification_result <> 'exact'::text) OR ((source_sha256 = reassembled_sha256) AND (source_byte_length = reassembled_byte_length) AND (covered_range_end = source_byte_length) AND (gap_count = 0) AND (overlap_count = 0)))),
    CONSTRAINT content_chunk_reassembly_receipt_chunk_count_check CHECK ((chunk_count >= 0)),
    CONSTRAINT content_chunk_reassembly_receipt_covered_range_start_check CHECK ((covered_range_start = 0)),
    CONSTRAINT content_chunk_reassembly_receipt_gap_count_check CHECK ((gap_count >= 0)),
    CONSTRAINT content_chunk_reassembly_receipt_member_count_check CHECK ((member_count >= 0)),
    CONSTRAINT content_chunk_reassembly_receipt_overlap_count_check CHECK ((overlap_count >= 0)),
    CONSTRAINT content_chunk_reassembly_receipt_reassembled_byte_length_check CHECK ((reassembled_byte_length >= 0)),
    CONSTRAINT content_chunk_reassembly_receipt_reassembled_sha256_check CHECK ((octet_length(reassembled_sha256) = 32)),
    CONSTRAINT content_chunk_reassembly_receipt_source_byte_length_check CHECK ((source_byte_length >= 0)),
    CONSTRAINT content_chunk_reassembly_receipt_source_sha256_check CHECK ((octet_length(source_sha256) = 32)),
    CONSTRAINT content_chunk_reassembly_receipt_verification_result_check CHECK ((verification_result = ANY (ARRAY['exact'::text, 'mismatch'::text, 'incomplete'::text, 'not_applicable'::text]))),
    CONSTRAINT content_chunk_reassembly_receipt_verifier_id_check CHECK ((length(btrim(verifier_id)) > 0)),
    CONSTRAINT content_chunk_reassembly_receipt_verifier_version_check CHECK ((length(btrim(verifier_version)) > 0))
);


