    CONSTRAINT evidence_vector_projection_job_authority_state_check CHECK ((authority_state = ANY (ARRAY['active'::text, 'revoked'::text, 'superseded'::text]))),
    CONSTRAINT evidence_vector_projection_job_check CHECK (((locked_at IS NULL) = (locked_by IS NULL))),
