    CONSTRAINT message_projection_route_decision_state_check CHECK ((decision_state = ANY (ARRAY['proposed'::text, 'approved'::text]))),
    CONSTRAINT message_projection_route_deriver_version_check CHECK ((length(deriver_version) > 0)),
    CONSTRAINT message_projection_route_projection_kind_check CHECK ((projection_kind = ANY (ARRAY['first_party'::text, 'acquired_third_party'::text]))),
    CONSTRAINT message_projection_route_proposed_by_check CHECK ((length(proposed_by) > 0))
);


