    proposer text NOT NULL,
    approval_state text DEFAULT 'proposed'::text NOT NULL,
    proposed_at timestamp with time zone DEFAULT now() NOT NULL,
    approved_at timestamp with time zone,
    approved_by text,
    notes text,
    CONSTRAINT realization_event_approval_state_check CHECK ((approval_state = ANY (ARRAY['proposed'::text, 'approved'::text, 'superseded'::text]))),
    CONSTRAINT realization_event_case_id_check CHECK ((length(case_id) > 0)),
    CONSTRAINT realization_event_check CHECK (((approved_at IS NULL) = (approval_state = 'proposed'::text))),
    CONSTRAINT realization_event_check1 CHECK (((approved_by IS NULL) = (approval_state = 'proposed'::text))),
    CONSTRAINT realization_event_evidence_pointer_check CHECK ((jsonb_typeof(evidence_pointer) = 'object'::text)),
    CONSTRAINT realization_event_kind_check CHECK ((kind = ANY (ARRAY['contradiction'::text, 'export_read'::text, 'told_by_person'::text, 'manual'::text, 'betrayal'::text, 'deceit'::text, 'gaslighting'::text, 'pattern_recognition'::text]))),
    CONSTRAINT realization_event_proposer_check CHECK ((proposer = ANY (ARRAY['algorithm'::text, 'owner'::text])))
);


