    source_clock_hash text NOT NULL,
    refreshed_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT record_visible_from_source_clock_hash_check CHECK ((length(source_clock_hash) = 64))
);


--
-- Name: TABLE record_visible_from; Type: COMMENT; Schema: working; Owner: -
--

COMMENT ON TABLE working.record_visible_from IS 'Materialized projection of working.visible_from (ADR-0045 §A) — the FAST path for the spine view. Sole writer = the derivation-engine refresher (W1.4 grants; pg_advisory_lock F13). A cached row is trusted only when its base_version matches app.base_version; otherwise the predicate recomputes from authored state. NULL source availability always denies. ';


--
-- Name: COLUMN record_visible_from.visible_from; Type: COMMENT; Schema: working; Owner: -
--

COMMENT ON COLUMN working.record_visible_from.visible_from IS 'Materialized source_available_from; NULL is an intentional fail-closed result, never an unknown allow.';


--
-- Name: COLUMN record_visible_from.base_version; Type: COMMENT; Schema: working; Owner: -
--

COMMENT ON COLUMN working.record_visible_from.base_version IS 'Exact vw_walk_base_version_input digest for which this cached source clock was computed.';


--
-- Name: review_queue; Type: VIEW; Schema: working; Owner: -
--

CREATE VIEW working.review_queue AS
 SELECT 'entity'::text AS kind,
    e.id,
    e.created_at,
    e.confidence,
    e.source_raw_table,
    e.source_raw_id,
    e.name AS label,
    e.review_state
   FROM working.candidate_entity e
  WHERE (e.review_state = 'pending'::text)
UNION ALL
 SELECT 'fact'::text AS kind,
    f.id,
    f.created_at,
    f.confidence,
    f.source_raw_table,
    f.source_raw_id,
    f.statement AS label,
    f.review_state
   FROM working.candidate_fact f
  WHERE (f.review_state = 'pending'::text)
UNION ALL
 SELECT 'event'::text AS kind,
    v.id,
    v.created_at,
    v.confidence,
    v.source_raw_table,
    v.source_raw_id,
    v.summary AS label,
    v.review_state
   FROM working.candidate_event v
  WHERE (v.review_state = 'pending'::text);


--
-- Name: VIEW review_queue; Type: COMMENT; Schema: working; Owner: -
--

COMMENT ON VIEW working.review_queue IS 'Everything awaiting human judgement, lowest-confidence first is the intended read: ORDER BY confidence NULLS FIRST, created_at.';


