    CONSTRAINT third_party_context_thread_version_check1 CHECK (((last_occurred_at IS NULL) OR (last_occurred_at >= first_occurred_at))),
    CONSTRAINT third_party_context_thread_version_check2 CHECK (((knowledge_available_from IS NULL) OR (first_occurred_at IS NULL) OR (knowledge_available_from >= first_occurred_at))),
    CONSTRAINT third_party_context_thread_version_check3 CHECK (((review_state <> 'approved'::text) OR ((reviewed_by IS NOT NULL) AND (reviewed_at IS NOT NULL)))),
    CONSTRAINT third_party_context_thread_version_classifier_id_check CHECK ((length(btrim(classifier_id)) > 0)),
    CONSTRAINT third_party_context_thread_version_classifier_version_check CHECK ((length(btrim(classifier_version)) > 0)),
    CONSTRAINT third_party_context_thread_version_confidence_check CHECK (((confidence >= (0)::double precision) AND (confidence <= (1)::double precision))),
    CONSTRAINT third_party_context_thread_version_review_state_check CHECK ((review_state = ANY (ARRAY['proposed'::text, 'approved'::text, 'rejected'::text, 'superseded'::text]))),
    CONSTRAINT third_party_context_thread_version_version_ordinal_check CHECK ((version_ordinal > 0))
);


